window.QUESTION_BANK.judge=[{"id":"judge-1","type":"judge","number":1,"stem":"（   ）职业道德的形式，因行业而异。一般来说，有多少种不同的行业，就有多少种不同的职业道德。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-2","type":"judge","number":2,"stem":"（   ）安检人员要自觉遵守党和国家的各项法律法规和政策规定。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-3","type":"judge","number":3,"stem":"（   ）民航安检工作是一项政策性、专业性与技术性很强的工作。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-4","type":"judge","number":4,"stem":"(   )安检人员成年累月地与旅客交往，一言一行都代表着企业的形象。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-5","type":"judge","number":5,"stem":"(   )规范执勤，优质服务，是安检人员职业道德规范的重要内容。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-6","type":"judge","number":6,"stem":"(   )安检人员良好的职业理想信念和职业道德境界，是职业道德养成的思想基础。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-7","type":"judge","number":7,"stem":"(   )安检员要真正做到规范执勤，应做到端正检查态度，规范安检执勤，正确认识严格检查、规范执勤、优质服务三者之间的辩证统一关系。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-8","type":"judge","number":8,"stem":"（   ）民航安全检查是一种职业技能，无论是证件检查、人员检查、物品检查还是异常行为人员的识别、仪器设备的检测维修实质上都是技术较密集型的岗位。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-9","type":"judge","number":9,"stem":"(   )每个安检人员应努力做到一专多能，技能上精益求精，人人成为合格的岗位技术能手。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-10","type":"judge","number":10,"stem":"（   ）安检人员职业道德规范是社会主义职业道德在民航安检职业活动中的具体体现。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-11","type":"judge","number":11,"stem":"（   ）民航安检工作是一项政策性、专业性与技术性很强的工作。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-12","type":"judge","number":12,"stem":"（   ）随着国际国内社会形势的不断变化，恐怖分子总在处心积虑地伺机而动，劫机、炸机、炸航站楼、袭击停机坪、入侵民航计算机系统等破坏行为，不一而足。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-13","type":"judge","number":13,"stem":"（   ）空防安全事关国家安全，每一位安检人员必须从认识上、情感上、信念上、意志上乃至习惯上养成忠于职守的自觉性。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-14","type":"judge","number":14,"stem":"按航空业务能力的不同，分为枢纽机场、干线机场、支线机场和通用机场。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-15","type":"judge","number":15,"stem":"按飞行区等级，依据指标I、Ⅱ进行划分，机场分为多种类型。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-16","type":"judge","number":16,"stem":"飞行区是机场内由建筑物和室外隔离设施所围合的区域，包含跑道、滑行道、机坪等设施和场地。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-17","type":"judge","number":17,"stem":"机场公安机关是指国家依法在机场设立的，对机场安保承担管理、监督、检查职责，独立执行覆盖民航系统全面安全保卫任务的专门公安机关。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-18","type":"judge","number":18,"stem":"对需要实施从严检查的旅客，不配合检查的可根据情况予以拒绝进入机场控制区或报告民用机场公安机关处理","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-19","type":"judge","number":19,"stem":"普通货物是对托运人没有特殊要求，承运人对货物没有特殊规定的货物","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-20","type":"judge","number":20,"stem":"托运人托运鲜活易腐物品，应当提供最长允许运输时限和运输注意事项，订妥舱位，按约定时间送机场办理托运手续。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-21","type":"judge","number":21,"stem":"快递的承运人可以是航空公司，航空货运代理公司或专门的快递公司","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-22","type":"judge","number":22,"stem":"弹药属于特种管制物品","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-23","type":"judge","number":23,"stem":"进出境各类枪械，弹药的国内运输必须出具边防检查站核发的携运证","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-24","type":"judge","number":24,"stem":"民航安全主要是由飞行安全和空防安全两部分组成","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-25","type":"judge","number":25,"stem":"民用航空货物承运人应当按照保证重点 照顾一般 合理运输，安全 迅速准确 经济地组织货物运输，体现人民航空为人民的宗旨","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-26","type":"judge","number":26,"stem":"周恩来总理指示民航要’保证安全第一，改善服务工作，争取飞行正常","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-27","type":"judge","number":27,"stem":"民航安检机构在安检勤务组织时，可以配备低于岗位人员资质标准要求的安检人员上岗运行","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-28","type":"judge","number":28,"stem":"民航安检机构安检勤务组织不用考虑安检职业资格要求","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-29","type":"judge","number":29,"stem":"民航安检机构坚持安检职业资格及岗位人员资质标准要求是为了规范安检工作","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-30","type":"judge","number":30,"stem":"民航安全检查设备可对乘坐民用航空器的旅客及其行李实施安全检查。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-31","type":"judge","number":31,"stem":"民航安全检查设施设备仅包括民航安全检查设备。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-32","type":"judge","number":32,"stem":"携带金属物品的人员通过通过式金属探测门时，对应的区域会有红色报警灯提示和报警声音。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-33","type":"judge","number":33,"stem":"通过式金属探测门根据机械结构划分出不同的探测区域。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-34","type":"judge","number":34,"stem":"手持金属探测器主要用于探测人员携带的金属物品。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-35","type":"judge","number":35,"stem":"手持金属探测器是通过自身产生变化频率磁场来探测金属物品的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-36","type":"judge","number":36,"stem":"毫米波人体成像安检仪可以检测出藏匿于衣物下的民航禁限运输物品。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-37","type":"judge","number":37,"stem":"毫米波人体成像安检仪不会对藏匿于衣物下的民航禁限运输物品位置进行标识。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-38","type":"judge","number":38,"stem":"毫米波人体成像安检仪检测结果是以声音的方式告知安检人员的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-39","type":"judge","number":39,"stem":"开箱包检查员应与民航行李安检设备操作员进行信息复述确认后，控制行李物品并与旅客确认箱包归属后，对行李物品进行开箱包检查。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-40","type":"judge","number":40,"stem":"按照图像分析方法，使用操作功能键对图像进行判读。确认无疑点后，方可做出放行决定。需要开箱包检查的，民航行李安检设备操作员应当向开箱包检查员明确开检箱包及重点开检区域。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-41","type":"judge","number":41,"stem":"对航空货邮快件实施安全检查前，货邮快件安检设备操作员应当审核航空货物、航空邮件托运人或者航空货运销售代理人提交的航空货运单或航空邮件邮包汇总路单、报关单、航空货物邮件安检申报清单、航空邮件快件品名数量详细清单及民航局认可的鉴定机构出具的运输条件鉴定书等航空货物运输文件资料。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-42","type":"judge","number":42,"stem":"我国作为国际民航组织的创始成员国之一，1975年，当选为二类理事国，2004年，当选为一类理事国。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-43","type":"judge","number":43,"stem":"《国际民用航空公约》规定航空器登记国有权对在机上的犯罪和犯罪行为行使管辖权，其主要目的是确立机长对航空器内犯罪的管辖权。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-44","type":"judge","number":44,"stem":"《东京公约》规定了在防止对国际民用航空进行非法干扰的行为的一切有关事务中，保证旅客、机组、地面人员和一般公众的安全是每个缔约国的首要目的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-45","type":"judge","number":45,"stem":"《海牙公约》全称为《关于在航空器内的犯罪和某些其他行为的公约》。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-46","type":"judge","number":46,"stem":"《海牙公约》的主要目的是防止非法劫持航空器。 （    ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-47","type":"judge","number":47,"stem":"《蒙特利尔公约》是在加拿大蒙特利尔签订的。 （    ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-48","type":"judge","number":48,"stem":"《蒙特利尔公约补充议定书》主要针对发生在国际民用航空服务机场\n上的非法暴力行为（    ）。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-49","type":"judge","number":49,"stem":"《北京公约》是国际民航史上首次以中国城市命名的国际公约。 （    ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-50","type":"judge","number":50,"stem":"《中华人民共和国民用航空法》是我国第一部规范民用航空活动的基本法律。（    ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-51","type":"judge","number":51,"stem":"从事特种作业的劳动者必须经过培训并取得特种作业资格。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-52","type":"judge","number":52,"stem":"民航安检员穿着民航安检制式服装应当整洁、无褶皱、无破损、无汗渍、无明显异味。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-53","type":"judge","number":53,"stem":"民航安检员穿着民航安检制式服装应当遵守换季时应统一换装，冬夏制服不得混穿。换装时间由所属机场管理机构确定。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-54","type":"judge","number":54,"stem":"民航安检员穿着民航安检制式服装时要举止端庄，可穿着民航安检制式服装出人休闲娱乐场所，但不能做出其他有损民航安检职业形象的言行举止。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-55","type":"judge","number":55,"stem":"航空犯罪心理学研究的是所有与航空相关人员的心理活动特征。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-56","type":"judge","number":56,"stem":"异常行为识别在国内最初就被称为“异常行为识别”（ABR）和“高风险旅客行为识别”(HRPE）。（  ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-57","type":"judge","number":57,"stem":"直觉或经验判断法完全不依赖任何客观依据。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-58","type":"judge","number":58,"stem":"严守党和国家的秘密，勿在外国人、外籍人面前谈论内部机密。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-59","type":"judge","number":59,"stem":"坚决维护国家主权、尊严和利益。不做有损于国家尊严的事，不说不利于国家声誉的话。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-60","type":"judge","number":60,"stem":"尊重不同国家、不同民族的风俗习惯和宗教信仰，随意干涉对方的内部事务。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-61","type":"judge","number":61,"stem":"我国是一个多民族国家，共有55个民族","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-62","type":"judge","number":62,"stem":"安检人员应使用舒缓的语速，并根据不同的对象、环境使用正确的语气","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-63","type":"judge","number":63,"stem":"严格按章办事，规范细致的解答旅客提出的问题，不能借故刁难旅客","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-64","type":"judge","number":64,"stem":"在民族自治地方，居民身份证可以只使用当地通用的少数民族文字进行登记。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-65","type":"judge","number":65,"stem":"中国居民身份证正面的缩微字符串是由“中华人民共和国国徽图案”汉语拼音字头组成的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-66","type":"judge","number":66,"stem":"临时居民身份证背面的“中国CHINA”字符采用光变光存储膜。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-67","type":"judge","number":67,"stem":"居民身份证证件背面性别项目位置的“长城”图案采用荧光油墨印刷。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-68","type":"judge","number":68,"stem":"中国人民武装警察部队文职人员证的封皮颜色是暗红色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-69","type":"judge","number":69,"stem":"护照是唯一可以证明一个人国籍的证件。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-70","type":"judge","number":70,"stem":"根据护照颁发对象的不同，我国护照分为外交护照、公务护照和普通护照三类。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-71","type":"judge","number":71,"stem":"电子护照是根据护照的使用目的分类的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-72","type":"judge","number":72,"stem":"自2019年6月1日起，我国公民往来港澳台地区的出入境证件由国家移民管理局签发。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-73","type":"judge","number":73,"stem":"外国人永久居留证件是外国人在中国居留期限不受限制的凭证，也是有永久居留资格的外国人在中国境内居留的合法身份证件，可以单独使用。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-74","type":"judge","number":74,"stem":"被批准在中国永久居留的18周岁以上的外国人，签发有效期为10年的证件。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-75","type":"judge","number":75,"stem":"外籍护照只有外交护照和普通护照两种。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-76","type":"judge","number":76,"stem":"外交人员证是由外交部礼宾司发给各国驻华大使馆中持有公务护照的外交代表及其配偶的身份证件。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-77","type":"judge","number":77,"stem":"验证检查主要包括证件真伪鉴别和人、证一致判断两个方面的内容。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-78","type":"judge","number":78,"stem":"一般采用仪器检查和人工检查两种方式。对于无法使用仪器进行检查的,可以通过对证件的外观式样、规格、大小、印刷和相片，以及护照的内页等主要识别特征进行人工检查，确认有无 变造、伪造的疑点，有无揭换相片。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-79","type":"judge","number":79,"stem":"护照识别仪将证件专用拍照设备的功能和电子护照读卡器 的功能融于一体，不但可以OCR 识别多种证件信息，还可以读取护照类证件的芯片 信息，真正实现各种证件的电子化自动录入。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-80","type":"judge","number":80,"stem":"人证一致判断应做到“指纹人像机具比对，观察询问要仔细”。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-81","type":"judge","number":81,"stem":"验证员到达验证岗位后，将安检验讫章放在验证台相应的位置，并登录民航安全 检查信息管理系统进入待检状态。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-82","type":"judge","number":82,"stem":"旅客购买国际(地区)中转国内或者国内中转国际(地区)联程机票，其国内航段的有效乘机身份证件使用国际(地区)航段登记的身份证件，不予以放行。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-83","type":"judge","number":83,"stem":"民航安检机构使用的安检验讫标识应当能够被有效查验、识别，通过使用安检验讫标识应能够有效区分已检和未检的人员及货物邮件。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-84","type":"judge","number":84,"stem":"航空货物应当依照航空货物安检要求通过民航货邮安检设备检查或其他检查方式。检查无疑点的，民航安检机构应当在航空货运清单、航空货物安检申报清单上加注 验讫标识，并留存航空货物安检申报清单后放行。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-85","type":"judge","number":85,"stem":"机场控制区通行证一般分为人员通行证和车辆通行证。人员通行证包括全民航统一制作的人员通行证、机场控制区人员通行证、车辆通行证。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-86","type":"judge","number":86,"stem":"车辆检查采用仪器检查和手工检查方式，包括对车底、车顶、车内、车身的检查。 车身、车内的检查重点包括驾驶室、承载室、储物箱、手扣、坐垫下、座椅下等位置， 必要时对发动机舱进行检查。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-87","type":"judge","number":87,"stem":"伪造证件从外观上看，可能会有粘贴的相片边缘有明显粘贴痕迹等问题。（  ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-88","type":"judge","number":88,"stem":"毫米波人体成像安检仪会对人体产生较大的辐射危害。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-89","type":"judge","number":89,"stem":"外籍旅客和台胞乘坐进藏航班，没有《进藏确认函》绝对不可以放行。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-90","type":"judge","number":90,"stem":"申领居民身份证期间，公安机关出具的贴有本人近期免冠证件照并加盖户籍专用章、注明有效期的《申领居民身份证回执》可作为乘坐国内航班的有效凭证。（  ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-91","type":"judge","number":91,"stem":"金属探测门的视觉警报信号高于报警界限值时显示黄色。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-92","type":"judge","number":92,"stem":"金属探测门的声音警报强度不能调节。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-93","type":"judge","number":93,"stem":"毫米波人体成像安检仪可以探测金属物品。（  ）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-94","type":"judge","number":94,"stem":"手持金属探测器(PD140N),根据要求选择工作方式(声响报警方式、振动报警方式、光学报警方式)。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-95","type":"judge","number":95,"stem":"手持金属探测器(PD140N),使用时，按下“L”按钮，可选择最高灵敏度(探测大型金属物品)；按下“M”按钮可选择中级灵敏度(探测中型金属物品)；按下“H”按钮可选择最低灵敏度(探测小型金属物品)。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-96","type":"judge","number":96,"stem":"前传引导检查员应观察人身检查员的工作情况，合理控制人员过检速度。若验证检查员验放速度过快，前传引导检查员应及时通知验证检查员控制速度;若人身检查员正在对受检人员进行检查，前传引导检查员应引导其他待检人员在人身安检设备外排队待检。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-97","type":"judge","number":97,"stem":"人身安检设备检查是指人身检查员为发现民航禁限运输物品，而按规定的程序和要求对受检人员进行的金属探测门设备检查或毫米波人体成像安检设备检查。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-98","type":"judge","number":98,"stem":"毫米波人体成像安检仪的使用操作程序(以MW1000AA为例)，人身检查员按照设备报警情况，对受检人员报警位置实施局部手工人身检查，并对全部受检人员进行脚部单独检查；按照抽检率要求对全部受检人员实施一定比例的抽检，抽检应采用全身手工人身检查的方式。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-99","type":"judge","number":99,"stem":"当出现传送带上物品散落、箱包被传送带卡死、液态物品泄漏等突发情况，民航行李安检设备操作员来不及反应时，前传引导检查员应迅速按下X射线安检仪紧急断电按钮给设备断电。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-100","type":"judge","number":100,"stem":"笔的检查。看笔的外观是否有异常，掂其重量是否与正常相符。通过检查，判断笔未被改装成笔枪或笔式爆炸物时，可按下开关或打开查看是否改装成笔刀。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-101","type":"judge","number":101,"stem":"国家对枪支管制非常严格，禁止任何单位或者个人违反法律规定持有、制造（包括变造、装配）、买卖、运输、出租、出借枪支。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-102","type":"judge","number":102,"stem":"按制造方法进行划分，枪支可分为制式枪和非制式枪。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-103","type":"judge","number":103,"stem":"部分制式手枪主要由枪管、复进机、套筒座、击发机、弹匣六部分组成。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-104","type":"judge","number":104,"stem":"具备枪支结构特征，并且具有与制式枪支材质和功能相似的枪管、枪机、机匣或者击发等机构之一的属于仿真枪。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-105","type":"judge","number":105,"stem":"外形、颜色与制式枪支相同或者近似，并且外形长度尺寸介于相应制式枪支全枪长度尺寸的二分之一与一倍之间的属于仿真枪。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-106","type":"judge","number":106,"stem":"从枪管内发射的弹药称为枪弹（子弹），主要由弹头、弹壳、底火、发射药四部分组成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-107","type":"judge","number":107,"stem":"毒品一般是指使人形成瘾癖的药物。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-108","type":"judge","number":108,"stem":"液态物品包括液体、凝胶、气溶胶等形态的固态物品。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-109","type":"judge","number":109,"stem":"对民航安检工作现场发现的遗失物品，应当由两名以上民航安检员共同清理、记录后，移交运输机场公司指定部门处理，并做好书面交接记录。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-110","type":"judge","number":110,"stem":"X射线安检仪紧急关机的程序重新开机时，只要逆时针旋转拔出这一按钮并按下电开关即可","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-111","type":"judge","number":111,"stem":"航空器安保检查，是指对旅客可能已经进入过的航空器内部的检查和对货 舱的检查，目的在于发现可疑物品、武器、爆炸物或其他危害航空安全的装置、物品和物质","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-112","type":"judge","number":112,"stem":"航空器安保搜查，是指对航空器内部和外部进行彻底检查，目的在于发现可疑物品、武器、爆炸物或其他危险装置、物品和物质","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-113","type":"judge","number":113,"stem":"发生航空器停场期间被非法接触的，根据运输机场公司指令，民航安检机构应当会同民用机 场公安机关，对航空器进行安保搜查","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-114","type":"judge","number":114,"stem":"使用单门单机布局毫米波人体成像设备时，在人工判图模式下，安检通道现场应至少配备1名操作员和2名人身检查员。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-115","type":"judge","number":115,"stem":"毫米波人体成像设备采用人工判图模式时，根据远程判图的反馈结果，按照设备报警情况，对受检人员报警位置实施局部手检，并对全部受检人员进行脚部单独检查。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-116","type":"judge","number":116,"stem":"服务犬是为残疾人生活或工作提供协助的特种犬，包括辅助犬、导听犬、导盲犬、缉毒犬。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-117","type":"judge","number":117,"stem":"对因公务需要进入机场控制区的国家安全机关或其他行政机关人员，应当核查其机场控制区证件，其人身免于检查。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-118","type":"judge","number":118,"stem":"亮度是光作用于人眼所引起的明亮程度的感觉。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-119","type":"judge","number":119,"stem":"对比度是显示器画面黑与白的比值，也就是从黑到白的渐变层次。比值越大，从黑到白的渐变层次就越多，从而色彩表现越丰富。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-120","type":"judge","number":120,"stem":"X射线安检仪图像灰度是所扫描物体的密度与厚度这两个参数的共同反应。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-121","type":"judge","number":121,"stem":"物体密度越大，灰度越大；厚度越大，灰度越大。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-122","type":"judge","number":122,"stem":"TNT炸药图像颜色呈橙色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-123","type":"judge","number":123,"stem":"黑火药的主要成分为硝酸钾、木炭粉、硫磺，其中硝酸钾图像颜色呈蓝色、木炭粉图像颜色呈橙色、硫磺图像颜色呈绿色，综合之后黑火药的图像颜色一般呈绿色。如果使用其他氧化剂替代硝酸钾，图像颜色将存在偏绿或偏蓝的差异。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-124","type":"judge","number":124,"stem":"当判读既有颜色浅又有颜色深的图像时，应使用图像加亮键。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-125","type":"judge","number":125,"stem":"金属保温杯主材质为金属，图像颜色呈蓝色。因其内容物不同，颜色会发生变化。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-126","type":"judge","number":126,"stem":"叠氮化铅为电点火头的常用药，因成分中含铅，图像颜色呈黑色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-127","type":"judge","number":127,"stem":"传送带前进键、倒退键、停止键控制传送带前进、倒退和停止。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-128","type":"judge","number":128,"stem":"金属拉链，除使用金属铝外，金属拉链图像颜色一般呈蓝色，受衣物等背景影响，图像可能会偏绿色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-129","type":"judge","number":129,"stem":"有部分商务旅客由于独自到外地出差，为了自身安全，可能会随身携带电击器等械具防身，检查时要重点关注，将其与小型电器区分开。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-130","type":"judge","number":130,"stem":"有部分女性旅客为了自身安全，可能会携带催泪喷射器和蜂鸣自卫器之类的防身器具，检查时注意与化妆品区分开，对橙色或绿色的瓶状物应提高警惕。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-131","type":"judge","number":131,"stem":"X射线安检仪图像判读的基本原则：从图像周围向中间进行判读；按照图像颜色的不同进行判读；按照图像所呈现的层次进行判读；结合图像判读方法辅助进行判读。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-132","type":"judge","number":132,"stem":"抓住图像中难以判明性质、 X射线穿不透的物品及有疑点的地方进行重点分析， 主要针对电器、电池、容器等检查属于图像判读的重点分析法","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-133","type":"judge","number":133,"stem":"联想分析法又称举一反三法 ，抓住某个物品的结构特征来推断其他同类物品。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-134","type":"judge","number":134,"stem":"X射线安检仪图像判读的方法共有12种","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-135","type":"judge","number":135,"stem":"在现场检查工作中运用浅深综合判读方式，既可以弥补判图时易遗洞某些区域的缺点，又可以使操作员直观掌握需要开箱包的区域，进而提高检查的速度和准确性。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-136","type":"judge","number":136,"stem":"角度分析法是联想物品各种角度的图像特征加以分析判断。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-137","type":"judge","number":137,"stem":"催泪喷射器是一种会有对人体感官产生强烈性刺激催泪剂的致命性武器。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-138","type":"judge","number":138,"stem":"电击器是一种瞬间即可产生高强度电压的器械，接触皮肤后可使人短时间丧失反抗能力。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-139","type":"judge","number":139,"stem":"延期电雷管在瞬发电雷管的基础上增加了电点火头。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-140","type":"judge","number":140,"stem":"瞬发雷管在火雷管结构的基础上增加了电点火头。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-141","type":"judge","number":141,"stem":"导爆索防湿性能良好,两端密封,放人0.5m深的常温静水中浸泡24h不影响传爆。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-142","type":"judge","number":142,"stem":"打火机是人们在生活中普遍使用的手动操作大型取火工具。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-143","type":"judge","number":143,"stem":"按压式电子打火机由按钮、电子打火器(由固定杆、压电晶体、电极片、铜帽组成)、燃烧阀、燃烧阀嘴、弹簧、风帽等结构部件组成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-144","type":"judge","number":144,"stem":"延期铝壳电雷管正放图像中脚线是红色的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-145","type":"judge","number":145,"stem":"铁壳导爆管雷管内部有加强帽。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-146","type":"judge","number":146,"stem":"霰弹的外观可明显看到红色、绿色、黑色等塑料弹壳和金属底火。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-147","type":"judge","number":147,"stem":"普通枪弹的弹壳底部在正放图像中呈较粗直线状。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-148","type":"judge","number":148,"stem":"覆铜钢壳电雷管的斜放图像与直放图像相似。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-149","type":"judge","number":149,"stem":"纸壳电雷管管体外观为黑色细长条圆柱体，管壳口部有金属压条和两根脚线。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-150","type":"judge","number":150,"stem":"铝壳火雷管直放图像呈圆形，因为雷管内装填有炸药所以边缘处呈橙色。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-151","type":"judge","number":151,"stem":"覆铜钢壳电雷管正放图像中管壳内可见呈黑色块状的电点火头结构。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-152","type":"judge","number":152,"stem":"铝壳火雷管斜放图像呈浅绿色轮廓，管壳前半部为空管，颜色较浅，管壳后半部装填有炸药，呈橙色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-153","type":"judge","number":153,"stem":"发射药主要成分是黑火药","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-154","type":"judge","number":154,"stem":"导火索外观为白色外层纸和土黄色包线，呈绳索状。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-155","type":"judge","number":155,"stem":"为了对导火索进行伪装，有时犯罪分子也会给导火索涂上其他颜色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-156","type":"judge","number":156,"stem":"导火索的正放、直放和斜放图像呈深绿色绳索状。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-157","type":"judge","number":157,"stem":"普通导爆索在图像中正放、直放和斜放图像呈浅橙色绳索状。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-158","type":"judge","number":158,"stem":"电线一般呈较细的绿色或蓝色线状结构，绝大部分电线都有与之相连的电器，如有线鼠标、电吹风各类充电器等","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-159","type":"judge","number":159,"stem":"拉火管外壳多为塑料壳或纸壳，由拉火杆、拉火丝、摩擦火帽、拉火管壳组成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-160","type":"judge","number":160,"stem":"塑料拉火管直放图像可见浅橙色外壳，内部无加强帽结构，呈浅橙色条状。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-161","type":"judge","number":161,"stem":"烟火制品在x射线安检仪中的图像呈现出从黄色到深蓝色等多种颜色。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-162","type":"judge","number":162,"stem":"为了在燃放烟花时获得有色火焰或闪光，需要在烟火剂中加入火焰着色物，使它燃烧时能把火焰“染成”特定颜色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-163","type":"judge","number":163,"stem":"线香类烟花的正放图像前半部沾烟火剂部分呈现蓝色线状，后半部手持部分呈现较细的浅橙色（竹竿）或蓝色（铁丝）线状。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-164","type":"judge","number":164,"stem":"线香类烟花的正放图像前半部手持部分呈现较细的浅橙色（竹竿）或蓝色（铁丝）线状。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-165","type":"judge","number":165,"stem":"吐珠类烟花能连续发射各种颜色亮珠，有地面吐珠和手持吐珠两种。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-166","type":"judge","number":166,"stem":"跳刀由金属刀身、金属或其他材质刀柄组成，刀身位于刀柄内部。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-167","type":"judge","number":167,"stem":"三棱刀由金属刀身和木质刀柄组成，刀身上有三条刀刃，斜放图像与直放图像相似。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-168","type":"judge","number":168,"stem":"催泪喷射器。在图像判读过程中应特别注意某些瓶装化妆品或生活用品 与催泪喷射器的区别，如发胶、剃须泡、口气清新剂、哮喘喷雾等，检查过程中发现 类似图像需通过开箱包检查进一步确认。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-169","type":"judge","number":169,"stem":"弩。弩属于机械反弹发力弹射装置，主要由弩臂、弩弓、弓弦、弩机几部 分构成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-170","type":"judge","number":170,"stem":"弩。为便于握持，常被设计成枪型。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-171","type":"judge","number":171,"stem":"打火机气体。正放图像轮廓明显，头部有金属充气管，较易判读；直放图像整体为椭圆形，内部有两 个同心圆，内部呈浅绿色，圆形中心可见呈黑色点状的金属充气管；斜放图像清晰可 见蓝色柱形瓶体和黑色金属充气管。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-172","type":"judge","number":172,"stem":"部分打火机气的体积小，并且大多成分属于原子序数小于10的物质，所以打火 机气正放、直放和斜放图像中瓶体轮廓不明显，呈浅橙色，一般通过头部的蓝色或黑 色金属充气管进行判读。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-173","type":"judge","number":173,"stem":"ZippO煤油。Zippo煤油瓶瓶身由金属制成，瓶体头部由塑料制成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-174","type":"judge","number":174,"stem":"ZippO煤油。斜放图像瓶体呈立方体，外部呈蓝色，内部呈浅绿色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-175","type":"judge","number":175,"stem":"塑料打火机：斜放图像外壳为浅橙色长方形，上部可见蓝色 方形风罩结构，内部可见蓝色细线。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-176","type":"judge","number":176,"stem":"金属打火机：直放图像外壳为蓝色长方形，火机头部可见蓝色圆形金属磨轮、蓝 色机盖与蓝色机体分隔明显；","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-177","type":"judge","number":177,"stem":"按压式打火机。在判读时注意使用结构分析法、重点分析法对此类打火机进行判读。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-178","type":"judge","number":178,"stem":"裁纸刀。裁纸刀的外壳通常有金属和塑料两种物质。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-179","type":"judge","number":179,"stem":"整盒裁纸刀片：直图像外部轮廓呈浅橙色，刀片呈深蓝色平行四边形，尾部有 圆孔；","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-180","type":"judge","number":180,"stem":"多节鞭。多节鞭主要由金属材料制成，有多个鞭节，鞭节之间有金属链相连。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-181","type":"judge","number":181,"stem":"()蜂鸣自卫器多为金属外壳，形状颜色统一。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-182","type":"judge","number":182,"stem":"()笔式催泪喷射器在X射线安检仪图像中直放图像内部呈橙色，中间有两个绿色同心圆。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-183","type":"judge","number":183,"stem":"()手表式点烟器外形与普通手表相类似，正放图像容易与一般手表相混淆。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-184","type":"judge","number":184,"stem":"()扳手是一种常用的安装与拆卸工具，通常用碳素或合金材料的结构钢制成。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-185","type":"judge","number":185,"stem":"()铁锤头部由金属制成，锤柄由木材、金属等材质制成。正放、直放及斜放图像的锤头轮廓特征非常明显，极易判读。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-186","type":"judge","number":186,"stem":"()橡胶锤头部由橡胶制成，锤柄由木材制成。正放、直放及斜放图像的绿色椭圆形锤头轮廓明显，木质锤柄呈绿色。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-187","type":"judge","number":187,"stem":"()蜂鸣自卫器多为塑料外壳，形状颜色不一。内部有电池等电子部件。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-188","type":"judge","number":188,"stem":"()信号枪正放图像可见枪底有明显的铆钉，枪头有浅蓝色的信号弹。直放图像较难判读，但可见上部的黑点状击发按钮。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-189","type":"judge","number":189,"stem":"()蝴蝶刀正放图像可见蓝色长方形模糊刀身及搭扣。直放图像呈黑色粗长线状。斜放图像和正放图像相似。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-190","type":"judge","number":190,"stem":"()带自锁装置的登山扣刀正放、斜放图像可见比较明显的刀身，直放图像刀身不明显，但可对深色部位进行重点分析，熟记图形。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-191","type":"judge","number":191,"stem":"()剃须刀式爆炸装置与正常的剃须刀相比，剃须刀式爆炸装置图像的电池图像旁有橙色块状物，其违反生活物品常规结构，故可作为该品的主要判读特征。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-192","type":"judge","number":192,"stem":"()U盘式点烟器属于点火器材，其正放、斜放图像有明显的USB 接口、中部电池和黑色点状点火电极。直放图像特征不明显，可通过图像右边的蓝黑色铆钉状进行辨识。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-193","type":"judge","number":193,"stem":"吸毒者通常采用呼吸道吸食、静脉和肌肉注射、直接服用等方式吸毒。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-194","type":"judge","number":194,"stem":"呼吸道吸食毒品，有时会用到报纸、瓶罐、水。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-195","type":"judge","number":195,"stem":"查毒技巧中，“提升”就是要不断总结毒品查缉的方法和规律，做到理论与实操相结合，不断提升毒品查缉的整体技能。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-196","type":"judge","number":196,"stem":"藏毒者在进入安检区后，因心理紧张会出现一些异常行为。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-197","type":"judge","number":197,"stem":"弹弓弓身材质为木制，其正放、直放、斜放图像颜色均为橙色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-198","type":"judge","number":198,"stem":"小型信号弹的正放图像外壳呈浅橙色正方形，内部有两个蓝色圆形。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-199","type":"judge","number":199,"stem":"乙醇在常温常压下是一种易燃、易挥发的无色透明液体，其蒸气能与空气形成爆炸性混合物。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-200","type":"judge","number":200,"stem":"梯恩梯炸药块的X射线图像呈橙色长方形，内部有放置雷管或导爆管的凹口状雷管室。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-201","type":"judge","number":201,"stem":"暖宝宝的X图像内部有颗粒状物体，形状不规则。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-202","type":"judge","number":202,"stem":"防晒霜的X射线图像中有蓝色密封盖，底部内凹，内部可见橙色或绿色液体。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-203","type":"judge","number":203,"stem":"棉签的顶部颜色呈橙色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-204","type":"judge","number":204,"stem":"烟花图像颜色均匀，且形状规则。食盐图像颜色具有层次感，大多为散装。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-205","type":"judge","number":205,"stem":"导火索相比跳绳整体颜色偏浅绿。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-206","type":"judge","number":206,"stem":"残疾旅客助残设备(包括拐杖、盲杖、轮椅等)必须通过民航行李安检设备检查，对不能通过民航行李安检设备检查的，经公共航空运输企业同意可直接放行。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-207","type":"judge","number":207,"stem":"专业照相器材、精密仪器原则上应通过民航行李安检设备检查；旅客提出不能通过民航行李安检设备的，应当进行手工检查和爆炸物探测检查，无需旅客进行操作演示。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-208","type":"judge","number":208,"stem":"开包工作站是民航安全检查信息管理系统的重要组成部分，主要用于采集、存储和记录被实施开箱包检查的受检人员基本信息及行李图像信息。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-209","type":"judge","number":209,"stem":"不同类型的旅客所携带的行李物品各有特点，安检人员掌握旅客及其行李物品的差异有助于维护空防安全，提高安检工作的质量；有助于掌握旅客心理，提高服务质量；有助于正确地了解自己，提高自身的心理素质。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-210","type":"judge","number":210,"stem":"乘机旅客的差异主要包括地区差异、气质差异、年龄差异、性别差异、职业差异、职务差异、散客与团体旅客的差异、初次乘机旅客与经常乘机旅客的差异。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-211","type":"judge","number":211,"stem":"整条香烟图像呈橙色长条盒状，使用图像加暗键，可见到单根香烟形状。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-212","type":"judge","number":212,"stem":"有些杂志、书籍使用轻涂纸或铜版 纸制作，图像多为绿色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-213","type":"judge","number":213,"stem":"衣物一般由绵、麻、丝、布等材料制成，图像颜色呈橙色，其衣物上的金属拉链、金属扣等金属制品呈蓝色或绿色。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-214","type":"judge","number":214,"stem":"对各种文物、工艺品进行检查，一般可采用摇晃、敲击、听等方法。摇晃或敲击时，听其有无杂音或异物晃动声。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-215","type":"judge","number":215,"stem":"文物、工艺品与容器类似，其外观形状、材质、用途种类繁多，其图像也多种多样，颜色因其具体材料而定。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-216","type":"judge","number":216,"stem":"儿童旅客：男孩可能携带塑料仿真枪、烟花、爆竹等物品， 一般会放在自己或父母的随身行李内。学生可能在文具袋(盒)内携带剪刀和裁纸刀等锐器。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-217","type":"judge","number":217,"stem":"化妆师：因其职业关系可能会携带大量化妆品，包括发胶、摩丝等压缩罐 及香水、指甲油、洗甲水等易燃液体。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-218","type":"judge","number":218,"stem":"手机型号多样，垂直视角图像可见蓝色电池、蓝色电板、蓝色CPU 等，水平视角图像颜色大部分呈蓝色块状。（ )","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-219","type":"judge","number":219,"stem":"收音机具有喇叭、天线等结构，使用图像增强键，可见呈蓝色金属圈状物的外放喇叭和蓝色金属管的天线。（ ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-220","type":"judge","number":220,"stem":"对旅客携带的神龛、神像等特殊物品，使用民航行李安检设备进行检查发现有异常物品时，可进行手工检查；在旅客不愿意通过民航行李安检设备检查时可采用手工检查或爆炸物探测检查。（ ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-221","type":"judge","number":221,"stem":"食品种类不同其图像也不尽相同但绝大部分呈橙色内部含有小包装干燥剂的罐、袋装食品会呈现出绿色颗粒状图像（ )","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-222","type":"judge","number":222,"stem":"粉末状物品性质不易确定，应取大量粉末状物品进行爆炸物探测检查，以确保该物品的安全性。（ )","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-223","type":"judge","number":223,"stem":"对收音机进行检查时，应观察其外观有无异常；打开电池盒盖，抽出接收天线，查看其是否藏匿有民航禁限运输物品；必要时，打开外壳检查内部。（ )","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-224","type":"judge","number":224,"stem":"笔一般使用塑料、树脂等制作，以长管型居多。X射线安检仪图像多为橙色管状、蓝色管状，加亮可见内部笔芯。一些笔因使用密度比较大的金属制作或制作工艺较复杂，图像或呈黑色。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-225","type":"judge","number":225,"stem":"对摄像机进行检查时，应观察其外观有无异常，有无可疑部件，有无拆卸过的痕迹；重点检查带匣、电池盒（外置电源）、取景窗等部分是否正常。对照相机进行检查时，可以掂其重量来判断是否正常；如机内没有胶卷，可以打开检查。（ )","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-226","type":"judge","number":226,"stem":"对手杖进行检查时，应敲击手杖，听其发声是否正常，认真检查是否被改成拐杖刀或拐杖枪。（ )","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-227","type":"judge","number":227,"stem":"转移防爆罐时需使用10米尼龙绳牵引。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-228","type":"judge","number":228,"stem":"热气球中可能含有易燃气体钢瓶。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-229","type":"judge","number":229,"stem":"家庭用品中可能含有腐蚀性烤箱清洁剂。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-230","type":"judge","number":230,"stem":"旅客行李中可能含有烟花。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-231","type":"judge","number":231,"stem":"黑火药含有硫黄，会发出\"臭鸡蛋\"（硫化氢）气味。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-232","type":"judge","number":232,"stem":"塑性炸药在使用时需要利用包装聚合。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-233","type":"judge","number":233,"stem":"TATP炸药因纯度不同，外观形状也有差异。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-234","type":"judge","number":234,"stem":"飞机零备件可能含有化学氧气发生器。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-235","type":"judge","number":235,"stem":"航空邮件申请安检前，邮政企业应当保证邮包封口、包装完好且单个邮包重量不超过30kg,并在安检申报清单上确认上述信息。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-236","type":"judge","number":236,"stem":"航空邮件图像显示与申报内容不符时，不用开箱检查，直接通知收件人。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-237","type":"judge","number":237,"stem":"航空快件无法排除疑点时，应加注安检退运标识，做退运处理。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-238","type":"judge","number":238,"stem":"对通过民航货邮安检设备检查有疑点的航空邮件，民航安检机构可单独进行开箱检查。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-239","type":"judge","number":239,"stem":"航空邮件邮包包装重量不符合规定时，应调整包装重量后继续运输。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-240","type":"judge","number":240,"stem":"伪报品名运输危险品，只需通知托运人整改即可。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-241","type":"judge","number":241,"stem":"属于国家规定的免检货物，核验民用机场公安机关出具的免检证明，免检 放行，并留存民用机场公安机关免检证明。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-242","type":"judge","number":242,"stem":"安检时发现可疑情形，托运人要求退运，应立即同意退运。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-243","type":"judge","number":243,"stem":"运离机场控制区的中转航空货邮快件重新进入时，无需进行安全检查。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-244","type":"judge","number":244,"stem":"对已经安全检查的航空货物，民航安检机构可以实施二次抽检。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-245","type":"judge","number":245,"stem":"2013年民航局公安局正式下发《民航安检现场旅客异常行为识别技术指南》, 从规范性文件的角度将异常行为识别的内容列入安检工作中。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-246","type":"judge","number":246,"stem":"异常行为是指其身体动作、肢体语言、面部表情及携带物品，缺乏正常迹象，不符合“基线”。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-247","type":"judge","number":247,"stem":"微表情是人在无意识中通过面部和动作的变化、语言的表述来将自己内心的真实 感受传达出来的本能反应。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-248","type":"judge","number":248,"stem":"面部表情是微表情的第一反应内容，也是微表情的重要内容之一。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-249","type":"judge","number":249,"stem":"惊讶的表情持续时间很短，如果超过1s，就可以判定这个人的惊讶是假的。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-250","type":"judge","number":250,"stem":"双视角X射线安检仪的设备功能——图像显示方式： 黑白、多能量、全彩色。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-251","type":"judge","number":251,"stem":"双视角X射线安检仪的垂直视角和水平视角两个图像相互配合、相辅相成，能使物品呈现得更清晰、更精准，能有效提高X光机操作员的检查效率，降低因图像模糊无法判读而需二次过检的概率。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-252","type":"judge","number":252,"stem":"定位角度分析法是操作员在水平视角图像判读过程中对有怀疑或无法准确辨识的物品，根据物品的位置定位，从垂直视角图像中将其找出，转换视角后识别其主要特征，从而判断其性质的一种判读方法。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-253","type":"judge","number":253,"stem":"叠影判图法是操作员在垂直视角图像判读过程中对有怀疑或无法准确辨识的物品，根据物品的位置定位，从水平视角图像中将其找出，转换视角后识别其主要特征，从而判断其性质的一种判读方法。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-254","type":"judge","number":254,"stem":"叠影判图法是针对图像中出现的多个重叠物品进行分离、构建、特征识别的综合型图像判读方法。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-255","type":"judge","number":255,"stem":"CT行李物品安检仪(以KylinTi为例)同时提供被检物品的计算机断层扫描(ComputedTomography,CT)切片图像、彩色高清三维立体图像及数字X射线摄影(DigitalRadiography,DR)图像，能清晰反映被检物品内容，帮助操作员更加方便有效地对图像进行人工判读。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-256","type":"judge","number":256,"stem":"CT技术是利用旋转的X射线源和面阵探测器，对被检物体进行180°的扫描，从而探测物体内部结构的一种先进探测技术。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-257","type":"judge","number":257,"stem":"CT行李物品安检仪鼠标的右键长按平移二维和CT切片图像。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-258","type":"judge","number":258,"stem":"CT行李物品安检仪鼠标的右键长按并沿嫌疑区域最大对角线，拖动鼠标从一点到另一点，可标记二维图像和CT切片图像中的嫌疑物。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-259","type":"judge","number":259,"stem":"CT行李物品安检仪显示界面中，增强指的是图像表面增强功能按键，CT图响应边缘增强效果，三维图响应表面增强效果。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-260","type":"judge","number":260,"stem":"CT行李物品安检仪显示界面中，开包率指的是显示嫌疑包裹计数与包裹总计数的比值。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-261","type":"judge","number":261,"stem":"叠影判图法的识别技巧中，首先，应识别重叠图像中容易识别的部分，结合整体重新对物品重叠部分进行构建，并将其从重叠部分中剥离出来，还原其整体形状后加以确认。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-262","type":"judge","number":262,"stem":"CT行李物品安检仪的X射线源和面阵探测器是固定不动的。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-263","type":"judge","number":263,"stem":"CT行李物品安检仪的三维旋转功能可以完全替代人工对箱包的检查。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-264","type":"judge","number":264,"stem":"CT行李物品安检仪三维旋转功能对被检物品的摆放方向有严格要求。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-265","type":"judge","number":265,"stem":"在安检过程中，CT行李物品安检仪三维旋转功能是发现违禁品的唯一有效手段。（  ）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-266","type":"judge","number":266,"stem":"雷汞是白色或灰色细粒状结晶体，且常用起爆药中感度最大的一种。（）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-267","type":"judge","number":267,"stem":"斯蒂酚酸铅主要用于电雷管的装填。（）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-268","type":"judge","number":268,"stem":"斯蒂酚酸铅是单质起爆药，亮黄色针状晶体，主要用于装填纸雷管。（）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-269","type":"judge","number":269,"stem":"二硝基重氮酚是单质起爆药，亮黄色针状晶体，但因工艺条件不同，可出现土黄、棕黄、黄绿、紫红等颜色。（）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-270","type":"judge","number":270,"stem":"起爆药包括黑索金。（）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-271","type":"judge","number":271,"stem":"猛炸药包括特屈儿。（）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-272","type":"judge","number":272,"stem":"火药分为黑火药和黑索金。（）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-273","type":"judge","number":273,"stem":"特种炸药包括塑性炸药、黏性炸药、橡皮炸药和液体炸药。（）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-274","type":"judge","number":274,"stem":"拉火管起爆的简易爆炸装置使用块状炸药时需要外壳,其图像除橙色的炸药部分外，可见火雷管、导火索、拉火管等图像特征。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-275","type":"judge","number":275,"stem":"电器类非制式爆炸装置，利用电器作为外壳，其图像可见电器内部空间或器件间隙正常，整体密度或颜色均匀，有雷管和多余导线等图像特征。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-276","type":"judge","number":276,"stem":"松发电引信不可改进为拉发电引信。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-277","type":"judge","number":277,"stem":"松发电引信的电雷管一根脚线与电池的一极相连，另一根脚线连接在开闭器的控制板上，压发杆由弹簧支撑，当压发杆上放置一定的重物时，弹簧处于压缩状态，移除重物后，弹簧的张力推动压发杆上移，使压发杆中间突出部分的金属片与控制板上的金属片相接，形成回路，引爆电雷管。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-278","type":"judge","number":278,"stem":"管材类非制式爆炸装置，利用日常生活中一些金属、塑料、橡胶等材质的管材作为外壳制作的爆炸装置，可用纸壳雷管引爆，也可用导火索引爆。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-279","type":"judge","number":279,"stem":"旅客携带不易确定性质的粉末状物品的情况处理方法中，复检仍报警的应立即将情况上报，同时启动应急预案进行处置。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-280","type":"judge","number":280,"stem":"航空安保管理体系的内容包括目标管理体系、组织保障体系、风险管理体系和质量控制体系。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-281","type":"judge","number":281,"stem":"属于少数民族人员在民族自治区域内携运或者境外旅客携运民族刀具的，可作为托运行李运输；其他人员携运民族刀具的,报告民用机场公安机关处理。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-282","type":"judge","number":282,"stem":"一般安全检查事件，包括但不限于以下情况：在托运行李安全检查工作中，未检出打火机；拆解的枪支弹药；枪支弹药和爆炸物品仿制品。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-283","type":"judge","number":283,"stem":"执行航班飞行任务的民用航空器在机坪短暂停留期间，由专人负责监护。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-284","type":"judge","number":284,"stem":"航空器在机场过夜或未执行航班飞行任务停放期间，应当由机舱管理机构守护。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-285","type":"judge","number":285,"stem":"航空器停放区域应当有充足的照明，确保守护人员及巡逻人员能够及时发现未经授权的非法接触。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-286","type":"judge","number":286,"stem":"航空安保业务外包的，机场管理机构应当与服务提供商签订安保协议，并对候机隔离区实施有效控制。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-287","type":"judge","number":287,"stem":"民航安检事件调查的目的应当遵循独立、客观、全面和深入的原则进行。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-288","type":"judge","number":288,"stem":"航空安保管理体系（SeMS）其内容包括目标管理体系、组织保障体系、风险管理体系和质量控制体系。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-289","type":"judge","number":289,"stem":"航空企业的安保措施执行规范文件，包含五个层级。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-290","type":"judge","number":290,"stem":"民航安检事件划分为特别严重安全检查事件、严重安全检查事件、一般安全检查事件、轻微安全检查事件四个等级。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-291","type":"judge","number":291,"stem":"民航地区管理局公安局负责组织实施特别严重和严重安检事件调查工作，民航监管局空防处负责组织实施一般和轻微安检事件调查工作。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-292","type":"judge","number":292,"stem":"航空安保检查是国家安全部门对民用航空运输机场和航空器经营人等民航企事业单位的航空安全保卫工作的部分领域实施客观检查，以核实其持续遵守《国家民用航空安全保卫方案》及其他航空安全保卫要求的情况。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-293","type":"judge","number":293,"stem":"航空安保测试是主管当局模拟实施扰乱行为，对民用航空运输机场和航空器经营人的相应航空安全保卫措施，进行的隐蔽或公开的试验。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-294","type":"judge","number":294,"stem":"民航安检质量控制中的内部测试，如果未通过测试，测试人员可不告知被测试人员测试项目的测试点。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-295","type":"judge","number":295,"stem":"演练形式和频次应参考危害程度、发生可能性、实际发生频率等因素，但应当保证实战演练每两年一次，桌面演练每半年一次；同时，每两年应对预案进行一次评估。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-296","type":"judge","number":296,"stem":"审计结束后应当形成报告，对审计中发现的不符合项只需提出纠正措施及完成期限，审计不符合项可不进行持续跟踪验证。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-297","type":"judge","number":297,"stem":"民航安检员离开机场控制区后，再次上岗前，其人身、行李、执勤着装和仪容、机场控制区通行证件佩戴应当接受检查。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-298","type":"judge","number":298,"stem":"民航安检员的机场控制区通行证件由民航安检机构集中统一管理。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-299","type":"judge","number":299,"stem":"“服务承诺法”：本着为旅客负责、以旅客为本的服务精神，分步解决旅客投诉的措施，是为缓和矛盾进一步升级所采取的一种策略。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-300","type":"judge","number":300,"stem":"“补偿关照法”：给予旅客物资或精神上补偿性关照的一种具体行动，其目的是让旅客知道被投诉人已经认识到其所犯的错误在任何情况下都是不能原谅的，也让旅客知道这种事情不会再发生。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-301","type":"judge","number":301,"stem":"“谅解法”：要求受理人在接受旅客投诉时，迅速核定事实，并向旅客表示歉意，安抚其情绪，尽量用旅客能够接受的方式取得旅客谅解的办法。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-302","type":"judge","number":302,"stem":"“引导征询法”是为了主动拒绝旅客需求。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-303","type":"judge","number":303,"stem":"“三明治法”是两片“面包”夹“拒绝” ，是一种与旅客沟通时避免说“不”的方法。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-304","type":"judge","number":304,"stem":"遇旅客投诉，安检员可以置之不理。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-305","type":"judge","number":305,"stem":"旅客投诉原因只有对安检工作不理解。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-306","type":"judge","number":306,"stem":"若旅客投诉合理是安检过错，不需要道歉。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-307","type":"judge","number":307,"stem":"民航安检机构不需要配备培训教员。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-308","type":"judge","number":308,"stem":"技能鉴定培训教员证书有效期为3年。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-309","type":"judge","number":309,"stem":"岗前技能培训是民航安全检查机构针对持有相应等级民航安全检查员国家职业资格证书，且初次从事相应安全检查岗位的人员；异地调动或者转岗或者脱离安全检查岗位时间超过6个月后重新从事相应安全检查岗位，经民航安全检查机构考试考核不合格的人员所进行的培训。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-310","type":"judge","number":310,"stem":"岗前技能培训涉及民航人身安全检查通道人员、民航交运行李安全检查人员、民航道口安全检查人员、民航货邮快件安全检查人员、民航安全检查勤务管理岗位人员、其他民航安全检查工作岗位人员等六类人员，因各类人员涉及的具体工作岗位不同，其岗前技能培训时间也有所不同。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-311","type":"judge","number":311,"stem":"各类人员涉及的具体工作岗位不同，其岗前技能培训时间也有所不同。其中维序检查岗位、道口人身检查岗位、限制物品移交岗位、防爆检查岗位的理论学习时间都是不低于6学时。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-312","type":"judge","number":312,"stem":"在岗技能保持培训可以使民航安全检查员的岗位技能、心理状态、身体状况能够持续满足相关民航安全检查岗位的工作。民航安全检查机构一般通过脱产培训、业务研究、岗位练兵等多种形式开展岗位技能知识培训。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-313","type":"judge","number":313,"stem":"在培训计划的种类中内容更多的是一些设想和打算，但一些具有长远战略眼光的单位也会做岀一些具体安排，诸如对一些具有培训前途人员的学历教育，目的是满足单位未来发展的要求，这是属于短期计划的表述。","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-314","type":"judge","number":314,"stem":"培训工作的法规依据包括：《国家民用航空安全保卫培训方案》《国家民用航空安全检查培训管理规定》《民航安全检查从业人员在职教育培训大纲》《民航安全检 查员职业技能鉴定培训管理办法》《关于对民航安全检查员国家职业资格证书实施复 审的通知》。","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-315","type":"judge","number":315,"stem":"Ｘ射线安检仪操作检查员连续操机工作时间不得超过40 分钟，再次操作 X 射线安检仪间隔时间不得少于 40分钟（）（民用航空安全检查规则第三章第十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-316","type":"judge","number":316,"stem":"民航安检机构设立单位应当按照民航局规定，上报民航安检设备使用验收检测、定期检测、报废等相关信息。（）（民用航空安全检查规则第四章第二十三条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-317","type":"judge","number":317,"stem":"民用运输机场管理机构应当设立专门的民航安检机构从事民航安检工作。()(民用航空安全检查规则第二章第八条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-318","type":"judge","number":318,"stem":"民航安检现场值班领导岗位管理人员应当具备民航安全检查员国家职业资格二级以上要求的理论和技能水平。（）（民用航空安全检查规则第三章第十五条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-319","type":"judge","number":319,"stem":"安全检查方式包括设备检查、手工检查及民航局规定的其他安全检查方式。()(民用航空安全检查规则第五章第二节第二十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-320","type":"judge","number":320,"stem":"十六周岁以下的中国大陆地区居民的有效乘机身份证件，还包括出生医学证明、户口簿、学生证或户口所在地公安机关出具的身份证明。（）（民用航空安全检查规则第五章第二节第三十一条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-321","type":"judge","number":321,"stem":"旅客应当依次通过人身安检设备接受人身检查。对通过人身安检设备检查报警的旅客，民航安全检查员应当对其采取重复通过人身安检设备或手工人身检查的方法进行复查，排除疑点后方可放行。对通过人身安检设备检查不报警的旅客不用检查（）。（民用航空安全检查规则第五章第二节第三十二条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-322","type":"judge","number":322,"stem":"对要求在非公开场所进行安全检查的旅客，如携带贵重物品、植入心脏起搏器的旅客和残疾旅客等，民航安检机构可以对其实施非公开检查。检查一般由两名以上与旅客同性别的民航安全检查员实施。（）（民用航空安全检查规则第五章第二节第三十五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-323","type":"judge","number":323,"stem":"旅客的随身行李物品应当经过民航行李安检设备检查。发现可疑物品时，民航安检机构应当实施开箱包检查等措施，排除疑点后方可放行。对没有疑点的随身行李物品可以实施开箱包抽查。实施开箱包检查时，无须旅客在场。（）（民用航空安全检查规则第五章第二节第三十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-324","type":"judge","number":324,"stem":"对来自境外，且在境内民用运输机场过站或中转的旅客及其行李物品，民航安检机构可不再实施安全检查。（民用航空安全检查规则第五章第二节第四十二条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-325","type":"judge","number":325,"stem":"对单体超大、超重等无法通过航空货物安检设备检查的航空货物，装入航空器前应当采取隔离停放至少 36小时安全措施，并实施爆炸物探测检查。（）（民用航空安全检查规则第五章第三节第四十九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-326","type":"judge","number":326,"stem":"“民用运输机场”，是指为从事旅客、货物运输等公共航空运输活动的民用航空器提供起飞、降落等服务的机场。包括民航运输机场和军民合用机场（）（民用航空安全检查规则第九章附则第八十八条 一）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-327","type":"judge","number":327,"stem":"对来自境内，且在境内民用运输机场过站或中转的旅客及其行李物品，民航安检机构不再实施安全检查。但旅客及其行李物品离开候机隔离区或与未经安全检查的人员、物品相混或者接触的除外。（）(民用航空安全检查规则第五章第二节第四十三）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-328","type":"judge","number":328,"stem":"“航空器安保检查”，是指对旅客可能已经进入的航空器内部的检查和对货舱的检查，目的在于发现可疑物品、武器、爆炸物或其他装置、物品和物质。（）（民用航空安全检查规则第九章附则第八十八条 十四）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-329","type":"judge","number":329,"stem":"危险品航空运输按照国家危险品航空运输有关规定执行。（）（民用航空安全检查规则第九章附则第八十九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-330","type":"judge","number":330,"stem":"民航安全检查员应当依据本规则和本机构民航安检工作运行管理文件的要求开展工作，执勤时不得从事与民航安检工作无关的活动。()(民用航空安全检查规则第三章第十七条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-331","type":"judge","number":331,"stem":"民航安检机构设立单位应当根据国家和民航局、地方人民政府有关规定，为民航安全检查员提供相应的岗位补助、津贴和工种补助。（）（民用航空安全检查规则第三章第十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-332","type":"judge","number":332,"stem":"“航空器安保搜查”是指对旅客可能已经进入的航空器内部的检查和对货舱的检查，目的在于发现可疑物品、武器、爆炸物或其他装置、物品和物质（） （民用航空安全检查规则第九章附则第八十八条 十四 十五）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-333","type":"judge","number":333,"stem":"民航安检机构设立单位或民航安检机构应当为安全检查员提供除法定假期外，每年不少于两周的带薪休假（）（民用航空安全检查规则第三章第二十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-334","type":"judge","number":334,"stem":"冲闯、堵塞民航安检通道或者民用运输机场控制区安检道口的民航安检机构应当采取紧急处置措施，并立即报告公安机关（）（民用航空安全检查规则第六章第六十四条二）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-335","type":"judge","number":335,"stem":"残疾旅客的助残设备、服务犬等无须接受安全检查。（）（民用航空安全检查规则第五章第二节第三十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-336","type":"judge","number":336,"stem":"民航安检机构应当根据本机构实际情况，与相关单位建立健全应急信息传递及报告工作程序，并建立记录。（）（民用航空安全检查规则第六章第六十七条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-337","type":"judge","number":337,"stem":"残疾旅客应当接受与其他旅客同样标准的安全检查。接受安全检查前，残疾旅客应当向安检机构确认具备乘机条件。（）（民用航空安全检查规则第五章第二节第三十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-338","type":"judge","number":338,"stem":"）伪造、变造、冒用危险品航空运输条件鉴定报告或者使用伪造、变造的危险品航空运输条件鉴定报告的民航安检机构应当报告公安机关()(民用航空安全检查规则第六章第六十三条六）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-339","type":"judge","number":339,"stem":"旅客的托运行李应当经过民航行李安检设备检查。发现可疑物品时，民航安检机构应当实施开箱包检查等措施，排除疑点后方可放行。对没有疑点的托运行李可以实施开箱包抽查。实施开箱包检查时旅客应当在场并确认箱包归属，但是公共航空运输企业与旅客有特殊约定的除外。（）（民用航空安全检查规则第五章第二节第三十八条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-340","type":"judge","number":340,"stem":"对通过民航货物安检设备检查有疑点、图像不清或者图像显示与申报不符的航空货物，民航安检机构应当采取开箱包检查等措施，排除疑点后加注验讫标识放行。无法排除疑点的，应当加注退运标识作退运处理。开箱包检查时，承运人应当在场。（）（民用航空安全检查规则第五章第三节第四十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-341","type":"judge","number":341,"stem":"旅客应当依次通过人身安检设备接受人身检查。对通过人身安检设备检查报警的旅客，民航安全检查员应当对其采取重复通过人身安检设备或手工人身检查的方法进行复查，排除疑点后方可放行。（）（民用航空安全检查规则第五章第二节第三十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-342","type":"judge","number":342,"stem":"对进入民用运输机场控制区的航空配餐和机上供应品，民航安检机构应当核查车厢是否锁闭，签封是否完好，签封编号与运输台帐记录是否一致。必要时可以进行随机抽查。（）（民用航空安全检查规则第五章第四节第五十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-343","type":"judge","number":343,"stem":"航空货物应当依照国务院规定，经过安全检查或者采取其他安全措施。（）（民用航空安全检查规则第五章第三节第四十五条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-344","type":"judge","number":344,"stem":"经过安全检查的旅客进入候机隔离区以前，民航安检机构应当对候机隔离区实施清场，实施民用运输机场控制区 24 小时持续安保管制的机场除外。（）（民用航空安全检查规则第五章第二节第四十四条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-345","type":"judge","number":345,"stem":"中国民用航空局、中国民用航空地区管理局（以下统称“民航行政机关”）对民航安检工作进行指导、检查和监督。（）（民用航空安全检查规则第一章第五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-346","type":"judge","number":346,"stem":"符合民用航空安全保卫设施行业标准要求的工作场地、设施设备和民航安检信息管理系统是民航安检机构的运行条件之一（）（民用航空安全检查规则第二章第十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-347","type":"judge","number":347,"stem":"民航安检机构应当根据民航局规定,制定并实施民航安检工作质量控制和培训管理制度，并建立相应的记录。（）（民用航空安全检查规则第二章第十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-348","type":"judge","number":348,"stem":"对不适合继续从事民航安检工作的人员，民航安检机构应当及时将其辞退。（）（民用航空安全检查规则第三章第十四条 三）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-349","type":"judge","number":349,"stem":"民航安全检查员执勤时应当着民航安检制式服装，佩戴民航安检专门标志。民航安检制式服装和专门标志式样和使用由国务院统一规定。（）（民用航空安全检查规则第三章第十六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-350","type":"judge","number":350,"stem":"从事民航安检设备使用验收检测、定期检测的人员无须通过民航局规定的培训。（）（民用航空安全检查规则第四章第二十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-351","type":"judge","number":351,"stem":"民航安检机构应当提供条件，保管或处理旅客在民航安检工作中暂存、自弃、遗留的物品。（）（民用航空安全检查规则第五章第二节第四十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-352","type":"judge","number":352,"stem":"民航安检机构应当按照民航局要求，实施民航安全检查安全信用制度。对有民航安检违规记录的人员和单位进行安全检查时，采取正常检查措施。（）（民用航空安全检查规则第五章第一节第二十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-353","type":"judge","number":353,"stem":"对航空邮件实施安全检查前，邮政企业应当提交经公共航空运输企业或其地面服务代理人审核的邮包路单和详细邮件品名、数量清单等文件资料或者电子数据()(民用航空安全检查规则第五章第三节第五十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-354","type":"judge","number":354,"stem":"进入民用运输机场控制区的其他人员、物品及车辆，应当接受安全检查。拒绝接受安全检查的，上报机场公安机关。（）（民用航空安全检查规则第五章第四节第五十三条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-355","type":"judge","number":355,"stem":"航空货物应当依照民航局规定，经过安全检查或者采取其他安全措施。（）（民用航空安全检查规则第五章第三节 第四十五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-356","type":"judge","number":356,"stem":"民航安检工作坚持安全第一、文明执勤的原则。（）（民用航空安全检查规则第一章第六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-357","type":"judge","number":357,"stem":"根据国家有关法律法规和民航危险品运输管理规定等相关要求，属于经公共航空运输企业批准方能作为随身行李物品或者托运行李运输的特殊物品，旅客凭公共航空运输企业同意承运证明，经安全检查确认安全后放行。（）（民用航空安全检查规则第五章第二节第三十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-358","type":"judge","number":358,"stem":"民航安检机构设立单位应当按照民航局规定，建立并运行民航安检设备的使用验收、维护、定期检测、改造及报废等管理制度，确保未经使用验收检测合格、未经定期检测合格的民航安检设备不得用于民航安检工作。()(民用航空安全检查规则第四章第二十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-359","type":"judge","number":359,"stem":"对于旅客提出需要暂存的物品，民用运输机场管理机构应当为其提供暂存服务。暂存物品的存放期限不超过一个月（）（民用航空安全检查规则第五章第二节第四十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-360","type":"judge","number":360,"stem":"从严检查措施应当由两名以上民航安全检查员在特别检查室实施。（）（民用航空安全检查规则第五章第二节第三十六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-361","type":"judge","number":361,"stem":"为了规范民用航空安全检查工作，防止对民用航空活动的非法干扰，维护民用航空运输安全，依据《中华人民共和国民用航空法》《中华人民共和国民用航空安全保卫条例》等有关法律、行政法规，制定本规则。（）（民用航空安全检查规则第一章第一条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-362","type":"judge","number":362,"stem":"进入民用运输机场控制区的旅客及其行李物品，航空货物、航空邮件应当接受安全检查。拒绝接受安全检查的，不得进入民用运输机场控制区。国务院规定免检的除外。()(民用航空安全检查规则第一章第四条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-363","type":"judge","number":363,"stem":"民用航空安全检查规则适用于在中华人民共和国境内的所有机场进 行的民用航空安全检查工作。（）（民用航空安全检查规则第一章第二条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-364","type":"judge","number":364,"stem":"《民用航空安全检查规则》已于 2016 年 8 月 31 日经第 19 次部务会议通过，现予公布，自 2017 年 1 月 1 日起施行。（）（民用航空安全检查规则文件开头）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-365","type":"judge","number":365,"stem":"对进入民用运输机场控制区的工具、物料或者器材，民航安检机构应当根据相关单位提交的工具、物料或者器材清单进行安全检查、核对和登记，带出时予以核销。工具、物料和器材含有民航禁止运输物品或限制运输物品的，民航安检机构应当要求其同时提供民用运输机场管理机构同意证明。（）（民用航空安全检查规则第五章第四节第五十六条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-366","type":"judge","number":366,"stem":"对进入民用运输机场控制区的民用航空监察员，民航安检机构应当核查其机场公安机关开具的临时证件并对其人身及物品进行安全检查。（）（民用航空安全检查规则第五章第四节第五十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-367","type":"judge","number":367,"stem":"民航安检机构应当依照本机构突发事件处置预案，不定期实施演练（）（民用航空安全检查规则第六章第六十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-368","type":"judge","number":368,"stem":"使用伪造、变造的乘机身份证件或者乘机凭证的民航安检机构应当报告公安机关（）（民用航空安全检查规则第六章第六十三条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-369","type":"judge","number":369,"stem":"民航安检机构及其设立单位应当积极配合民航行政机关依法履行指导监督职责，不得拒绝、阻挠。（）(民用航空安全检查规则第七章六十九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-370","type":"judge","number":370,"stem":"民航行政机关应当建立民航安检工作违法违规行为信息库，如实记录民航安检机构及其设立单位的违法行为信息。对违法行为情节严重的单位，应当纳入行业安全评价体系，并通报其上级政府主管部门。()(民用航空安全检查规则第七章第七十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-371","type":"judge","number":371,"stem":"在民用运输机场控制区以外区域进行的安全检查活动，参照《民用航空安全检查规则》有关规定执行。（民用航空安全检查规则第九章附则第九十一条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-372","type":"judge","number":372,"stem":"民用航空安全检查规则（交通运输部令 2016 年第 76 号）本规则自 2017 年 1 月 1 日起施行。1999 年 6 月 1日起施行的《中国民用航空安全检查规则》（民航总局令第 85 号）同时废止（）（民用航空安全检查规则第九章附则第九十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-373","type":"judge","number":373,"stem":"( )公共航空运输企业不得运输法律、行政法规规定的禁运物品。公共航空运输企业未经民航局公安局的批准，不得运输作战军火、作战物资。(中华人民共和国民用航空法第九十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-374","type":"judge","number":374,"stem":"( )候机隔离区应当根据安全保卫的需要，划定为候机隔离区、行李分检装卸区、航空器活动区和维修区、货物存放区等，并分别设置安全防护设施和明显标志。(中华人民共和国民用航空安全保卫条例第十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-375","type":"judge","number":375,"stem":"( )机场控制区应当有严密的安全保卫措施，实行封闭式分区管理。具体管理办法由民航行政机关制定。(中华人民共和国民用航空安全保卫条例第十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-376","type":"judge","number":376,"stem":"( )停放在机场的民用航空器必须有专人守卫；各有关部门及其工作人员必须严格执行航空器警卫交接制度。(中华人民共和国民用航空安全保卫条例第十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-377","type":"judge","number":377,"stem":"( )备用锂电池和充电宝外部应标明锂电池的额定容量和标称电压，或者标明锂电池的额定能量。（锂电池航空运输规范7锂电池作为行李运输的要求7.8.1）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-378","type":"judge","number":378,"stem":"( )民航安检现场旅客异常行为指征主要包括乘机身份证件类、携带物品类、外表着装类、行为动作类、语言表述类以及其它等六个类别。。(民航安检现场旅客异常行为识别技术指南2.2)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-379","type":"judge","number":379,"stem":"( )“持有全新护照的”属于民航安检现场旅客异常行为指征——乘机身份证件类。(民航安检现场旅客异常行为识别技术指南2.2.1)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-380","type":"judge","number":380,"stem":"( )携带雨伞、拐杖等易藏匿违禁物品的物品或可以用作作案工具的，属于民航安检现场旅客异常行为指征携带物品类。(民航安检现场旅客异常行为识别技术指南2.2.2)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-381","type":"judge","number":381,"stem":"( )检查过程中故意指责刁难、声称投诉或者大声叫嚷等，意图转移注意的是民航安检现场旅客异常行为指征中的行为动作类。(民航安检现场旅客异常行为识别技术指南2.2.4)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-382","type":"judge","number":382,"stem":"( )道具枪属于民用枪。(民航旅客禁止随身携带和托运物品名录一、枪支等武器（包括主要零部件）)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-383","type":"judge","number":383,"stem":"( )根据《民航旅客禁止随身携带和托运物品目录》，照明弹、燃烧弹、礼花弹、烟雾弹都属于弹药类。（民航旅客禁止随身携带和托运物品目录第二条爆炸或者燃烧物质和装置）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-384","type":"judge","number":384,"stem":"( )根据《民航旅客禁止随身携带和托运物品目录》，铅弹、信号弹、烟幕弹、礼花弹都属于弹药类。（民航旅客禁止随身携带和托运物品目录第二条爆炸或者燃烧物质和装置）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-385","type":"judge","number":385,"stem":"( )根据《民航旅客禁止随身携带和托运物品目录》，管制器具是指能够造成人身严重伤害或者对航空安全和运输秩序构成较大危害的管制器具。（民航旅客禁止随身携带和托运物品目录第三条管制器具）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-386","type":"judge","number":386,"stem":"( )根据《民航旅客禁止随身携带和托运物品目录》，额定能量超过160WH的充电宝、锂电池不能随身携带和托运（电动轮椅使用的锂电池另有规定）。（民航旅客禁止随身携带和托运物品目录第五条其他物品）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-387","type":"judge","number":387,"stem":"( )根据《民航旅客禁止随身携带和托运物品目录》，强磁化物、有强烈刺激性气味或者容易引起旅客恐慌情绪的物品以及不能判明性质可能具有危险性的物品属于民航禁止运输物品。（民航旅客禁止随身携带和托运物品目录第五条其他物品）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-388","type":"judge","number":388,"stem":"( )手术刀是禁止随身携带但可以作为行李托运的物品。(《民航旅客限制随身携带或托运物品目录》一（一））","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-389","type":"judge","number":389,"stem":"( )锐器包括菜刀、水果刀、剪刀、屠宰刀等日用刀具。(民用旅客限制随身携带或托运物品的目录一（一）)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-390","type":"judge","number":390,"stem":"( )棍棒、球棒、桌球杆、登山杖、冰镐等都属于禁止随身携带但可作为行李托运的物品中的钝器。(民用旅客限制随身携带或托运物品的目录一（二）)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-391","type":"judge","number":391,"stem":"( )作为托运行李，酒精的体积百分含量大于24%、小于或等于70%时，每位旅客托运数量不超过10L。(《民航旅客限制随身携带或托运物品目录》第二条第二项)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-392","type":"judge","number":392,"stem":"( )充电宝额定能量大于100WH、小于或等于160WH时必须经航空公司批准且每人限带两块。(《民航旅客限制随身携带或托运物品目录》第二条第三项)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-393","type":"judge","number":393,"stem":"（ ）为规范民用航空安全检查工作，统一民航安检工作标准，保证民航安检工作措施有效实施，依据《中华人民共和国民用航空安全保卫条例》和《民用航空安全检查规则》，制定《民用航空安全检查工作手册》。（民用航空安全检查工作手册第一章总则第1条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-394","type":"judge","number":394,"stem":"（ ）民航安检机构组织开展民航安检工作，以及与民航安检工作相关的单位和个人，应当遵守民用航空安全检查工作手册。(《民用航空安全检查工作手册》第一章总则第2条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-395","type":"judge","number":395,"stem":"（ ）根据国家法律、法规、规章、标准和《中华人民共和国民用航空法》等有关规定，制定并适时更新本机构民航安检工作运行管理文件。(《民用航空安全检查工作手册》第一章总则第3条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-396","type":"judge","number":396,"stem":"（ ）民航安检机构应当实施、开展民航行政机关和有关部门依法开展的监督、检查工作。(《民用航空安全检查工作手册》第一章总则第4条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-397","type":"judge","number":397,"stem":"（ ）民航安检机构具备民航局规定的运行条件后，方可组织开展民航安检工作。(《民用航空安全检查工作手册》第一章总则第5条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-398","type":"judge","number":398,"stem":"（ ）民航局应当根据有关规定和国家有关部门职责，将民航安检工作中发现的违法违规案(事)件的相关人员、物品、证据材料等移交、报告国家有关部门调查处理。(《民用航空安全检查工作手册》第一章总则第七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-399","type":"judge","number":399,"stem":"（ ）民航安检业务教育培训经费应当按照国家法律、法规和财政部关于企业职工教育经费提取与使用管理的意见等规定，予以足额保障。(《民用航空安全检查工作手册》第一章总则第8条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-400","type":"judge","number":400,"stem":"（ ）民航公安机关应当根据民航局有关规定实施本机构民航安检质量管理制度，制定质量控制方案和工作计划，组织实施质量控制活动，并建立质量控制工作记录。(《民用航空安全检查工作手册》第一章总则第9条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-401","type":"judge","number":401,"stem":"（ ）（ ）民航安检机构应当按照民航局安保应急演练有关要求，制定本机构民航安检突发事件应急处置预案，定期开展演练，并根据演练情况适时调整完善应急处置预案。（民用航空安全检查工作手册第一章总则第十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-402","type":"judge","number":402,"stem":"（ ）民航安检机构设立的运行条件，应当符合《民用航空安全检查规则》第十条规定的要求，并通过民航局航空安保管理机构审查。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第11条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-403","type":"judge","number":403,"stem":"（ ）民航安检机构运行条件申请审查时，应当向民航行政机关提交的材料包括有：民航安检机构设立单位在组织管理体系中的地位、工作任务和职责。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第12条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-404","type":"judge","number":404,"stem":"（ ）民航安检工作运行管理文件是民航安检机构正常开展民航安检工作的依据和职责，由民航安检业务管理手册、民航安检岗位作业手册等文件组成。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第13条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-405","type":"judge","number":405,"stem":"（ ）民航安检业务管理手册至少应当包括：民航安检工作任务和职责；民航安检工作依据和标准目录体系；民航安检机构组织架构及分工情况等内容。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第14条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-406","type":"judge","number":406,"stem":"（ ）民航安检业务管理手册至少应当包括民航安检工作岗位工作职责和作业流程；民航安检工作岗位勤务实施规程和服务规范；民航安检工作岗位特殊情况处置及信息报告；民航安检工作岗位作业台账和记录表单；民航安检岗位作业手册批准程序及修订记录等。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第15条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-407","type":"judge","number":407,"stem":"（ ）民航安检机构运行条件接受审查后，民航行政机关应当做出书面审查意见，并作为做出运输机场公司使用许可、公共航空运输企业运行合格审定决定的安保条件之一。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第16条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-408","type":"judge","number":408,"stem":"（ ）民航安检机构的运行条件应当接受民航行政机关定期审查，确保持续符合。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第17条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-409","type":"judge","number":409,"stem":"（ ）民航安检机构运行条件发生重大变化的，民航安检机构或者其设立单位应当在5个工作日内向所属民航地区管理局公安局及监管局空防处报告。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第18条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-410","type":"judge","number":410,"stem":"（ ）民航安检机构应当根据客货吞吐量和民航安检工作实际需要，科学合理设置内设部门，配置管理岗位，保证民航安检工作的有效管理和实施(《民用航空安全检查工作手册》第二章民航安检机构运行管理第19条。)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-411","type":"judge","number":411,"stem":"（ ）专、兼职质控人员数量应当与本机构民航安检工作质量控制业务相适应。其中一线生 产岗位 18 人以上 100 人（含）以下的，专职质控人员 1 人，一线生产岗位 18 人以下的可以 由现场勤务管理人员兼任质控人员。（民用航空安全检查工作手册第二章民航安检机构运行管理第二十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-412","type":"judge","number":412,"stem":"（ ）年旅客吞吐量2000万人次及以上运输机场公司的民航安检机构，应当设置勤务指挥调度部门，配备人员，统一指挥、调度、协调、管理民航安检现场勤务和突发事件的应急处置工作。(民用航空安全检查工作手册第二章 民航安检机构运行管理 第二十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-413","type":"judge","number":413,"stem":"（ ）民航安检机构应当按照有关规定，设置基层党组织和团组织，设置妇联、工会等基层群团组织，配备人员，提供经费，保障相关组织活动正常开展。(民用航空安全检查手册第二章民航安检机构运行管理第二十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-414","type":"judge","number":414,"stem":"（ ）民航安检机构应当建立安全目标责任制度，制定本机构民航安检工作年度安全目标和工作方案，并对内设部门和人员进行年度安全目标考核。(《民用航空安全检查工作手册》第24条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-415","type":"judge","number":415,"stem":"（ ）民航安检机构应当建立领导分级值班制度。民航安检机构领导应当现场值班。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第25条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-416","type":"judge","number":416,"stem":"（ ）民航安检机构应当建立安检信息报告制度，制定民航安检信息报送管理程序。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第27条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-417","type":"judge","number":417,"stem":"（ ）民航安检机构应当建立民航安检工作运行管理文件查阅管理制度。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第28条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-418","type":"judge","number":418,"stem":"（ ）保密范围依照国家、行业和地方人民政府有关规定确定。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第29条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-419","type":"judge","number":419,"stem":"（ ）民航安检机构使用的安检验讫标识应当能够被有效查验、识别，通过使用安检验讫标识应能够有效区分已检和未检的人员及货物邮件。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第30条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-420","type":"judge","number":420,"stem":"（ ）民航安检机构应当与公共航空运输企业地面服务机构、运输机场公司、民用机场公安机关和其他运输机场驻场单位建立信息共享和协作沟通机制，加强联系配合，确保信息沟通顺畅、协作配合有效，确保民航安检工作顺利进行。(《民用航空安全检查工作手册》第31条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-421","type":"judge","number":421,"stem":"（ ）同一民航安检机构使用多种用工方式的，应当实行同工不同酬。(民用航空安全检查工作手册第二章 民航安检机构运行管理 第三十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-422","type":"judge","number":422,"stem":"（ ）民航安检员流失后，对流失的民航安检员，民航安检机构应当建立制度或者采取适当措施，但无需了解人员流向。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第33条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-423","type":"judge","number":423,"stem":"（ ）民航安检机构应当对招录的民航安检员进行能力测评，确保其具备与所从事岗位工作相适应的身体素质、能力水平和心理状态。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第34条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-424","type":"judge","number":424,"stem":"（ ）民航安检员岗位技能评估多次考核未通过，民航安检机构应当及时向民航安检机构设立单位提出对其进行重新培训。(民用航空安全检查手册第二章民航安检机构运行管理第三十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-425","type":"judge","number":425,"stem":"（ ）民航安检员职业能力无法达到岗位要求或者从事民航安检工作差错率低于考核指标的，民航安检机构应当暂停或者取消其民航安检工作岗位操作授权。（民用航空安全检查工作手册第二章民航安检机构运行管理第三十六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-426","type":"judge","number":426,"stem":"（ ）岗位技能评估多次考核未通过，无法从事民航安检岗位工作的民航安检机构应当及时向民航安检机构设立单位提出调离安检工作岗位。(民用航空安全检查工作手册第二章 民航安检机构运行管理 第三十七条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-427","type":"judge","number":427,"stem":"（ ）民航安检员执勤着装和仪容管理具体要求按照《民用航空安全检查工作手册》附件一管理。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第38条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-428","type":"judge","number":428,"stem":"（ ）民航安检机构不得在民航安检员从事民航安检岗位工作时，为其安排与其执勤岗位工作无关的工作和活动。（民用航空安全检查手册第二章第三十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-429","type":"judge","number":429,"stem":"（ ）X射线安检仪操作检查员连续操机工作时间不足30分钟，但持续在岗位待岗的，X射线安检仪操作检查员操机时间应按照《民用航空安全检查规则》第十七条的要求执行。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第40条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-430","type":"judge","number":430,"stem":"（ ）民航安检机构作为民航安检设备使用单位，应当参与民航安检流程设计及民航安检设备招投标技术指标确定工作。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第41条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-431","type":"judge","number":431,"stem":"（ ）民航安检机构应当按照规定将民航安检设备使用验收技术检测记录报民航公安机关。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第42条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-432","type":"judge","number":432,"stem":"（ ）民航在用安检设备的技术档案、使用说明和操作规范应当在民航安检工作现场放置，以备查阅。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第43条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-433","type":"judge","number":433,"stem":"（ ）没有定期检测合格标签的民航在用安检设备，只要运行正常，照样可以用于民航安检工作。（民用航空安全检查手册第二章第四十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-434","type":"judge","number":434,"stem":"（ ）民航安检机构开始民航安检日常勤务后，应当组织实施民航在用安检设备及辅助设施日常检测，确认其具备使用条件。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第45条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-435","type":"judge","number":435,"stem":"（ ）民航安检设备设施发生故障无法及时修复的，应当立即通知民航安检机构负责人及时处理。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第46条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-436","type":"judge","number":436,"stem":"（ ）民航安检机构使用新技术类安检设备的，应当对新技术类安检设备操作人员进行设备功能和操作规范培训。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第47条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-437","type":"judge","number":437,"stem":"（ ）民航安检机构使用对人身安全、财产安全和环境安全具有或者可能具有危害的民航安检设备，应当要求设备生产制造厂商提供详细的安全提示，在设备显著位置张贴安全标识。(《民用航空安全检查工作手册》第二章民航安检机构运行管理第48条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-438","type":"judge","number":438,"stem":"（ ）维序检查岗位职责之一是：观察待检区情况，对待检人员进行分类识别和分流疏导，引导内部人员正确使用特殊通道，维持待检区域秩序。(《民用航空安全检查工作手册》民航安检员岗位职责第49条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-439","type":"judge","number":439,"stem":"（ ）验证检查岗位职责包括查验通行人员的机场控制区通行证件或者有效乘机凭证（民用航空安全检查工作手册第三章民航安检员岗位职责第五十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-440","type":"judge","number":440,"stem":"（ ）前传引导检查岗位职责之一是：引导受检人员有序、有效通过民航人身安检设备。(《民用航空安全检查工作手册》民航安检员岗位职责第51条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-441","type":"judge","number":441,"stem":"（ ）人身检查岗位职责之一是：维护民航人身安检设备前秩序。(《民用航空安全检查工作手册》民航安检员岗位职责第52条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-442","type":"judge","number":442,"stem":"（ ）民航行李安检设备操作岗位职责之一是：按照判图分析方法，使用操作功能键对图像进行判读，发现、辨认民航禁止随身携带物品或可疑图像。(《民用航空安全检查工作手册》民航安检员岗位职责第53条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-443","type":"judge","number":443,"stem":"（ ）行李物品开箱包检查岗位职责之一是：通知防爆检查岗位对疑似爆炸物品、爆炸装置或者无法确认性质的可疑行李物品进行防爆检查。(《民用航空安全检查工作手册》民航安检员岗位职责第54条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-444","type":"judge","number":444,"stem":"（ ）货邮快件安检设备操作岗位职责之一包括：按规定处置发现的民航禁限运输物品及携运人员。(《民用航空安全检查工作手册》民航安检员岗位职责第55条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-445","type":"judge","number":445,"stem":"（ ）货邮快件开箱检查岗位职责之一包括：通知防爆检查岗位对疑似爆炸物品、爆炸装置或者无法确认性质的可疑行李物品进行防爆检查。(《民用航空安全检查工作手册》民航安检员岗位职责第56条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-446","type":"judge","number":446,"stem":"（ ）限制物品移交岗位职责之一包括：向民用机场公安机关等部门报告民航安检工作现场发现的违法案(事)件，移交有关人员、物品和证据资料。(《民用航空安全检查工作手册》民航安检员岗位职责第57条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-447","type":"judge","number":447,"stem":"（ ）民航安检工作现场防爆检查岗位职责之一包括：负责其他发生事项的政策解释工作。(《民用航空安全检查工作手册》民航安检员岗位职责第58条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-448","type":"judge","number":448,"stem":"（ ）机场控制区道口车辆检查岗位职责之一包括：管理、维护机场控制区道口秩序，引导、安排车辆有序受检。(《民用航空安全检查工作手册》民航安检员岗位职责第59条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-449","type":"judge","number":449,"stem":"（ ）民航安检现场值班领导岗位职责之一包括：按规定对可疑车辆及物品采取处置措施。（《民用航空安全检查工作手册》民航安检员岗位职责第60条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-450","type":"judge","number":450,"stem":"（ ）安全检查信息管理系统操作岗位职责之一包括：将民用机场公安机关布控信息录入民航安检信息系统。(《民用航空安全检查工作手册》民航安检员岗位职责第61条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-451","type":"judge","number":451,"stem":"（ ）安全检查质量监察岗位职责包括分析质量监察结果，编制质量监察报告，提出改进意见，跟踪、督查、评估整 改措施的落实情况。（民用航空安全检查工作手册第三章民航安检员岗位职责第六十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-452","type":"judge","number":452,"stem":"（ ）安全检查业务培训岗位职责包括编制培训大纲，制定培训计划，编写民航安检工作培训教案和培训课件（民用航空安全检查工作手册第三章民航安检员岗位职责第六十三条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-453","type":"judge","number":453,"stem":"（ ）安全检查设备维修岗位职责包括对民航在用安检设备进行定期或不定期的巡视、维护、保养和维修。（民用航空安全检查工作手册第三章民航安检员岗位职责第六十四条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-454","type":"judge","number":454,"stem":"（ ）异常行为识别岗位职责之一包括：向民航安检现场岗位发布异常行为人员安全提示。(《民用航空安全检查工作手册》民航安检员岗位职责第65条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-455","type":"judge","number":455,"stem":"（ ）通行管制岗位职责之一包括：向民航安检现场岗位发布异常行为人员安全提示。(《民用航空安全检查工作手册》第三章民航安检员岗位职责66条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-456","type":"judge","number":456,"stem":"（ ）民航安检机构组织和实施民航安检工作勤务时，应当以分队（或者班、组）等建制单位安检，采取分级指挥、分级负责的方法，使各级职、责、权分明。（民用航空安全检查手册第四章民航安检工作实施第六十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-457","type":"judge","number":457,"stem":"（ ）民航安检机构实施民航安检勤务时，应当对民航安检工作现场实施安全管控。民航安检员应当落实岗位工作责任制，做到熟悉勤务方案，明确自身任务，严格按照岗位职责开展勤务工作。 (民用航空安全检查手册第四章民航安检工作实施第六十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-458","type":"judge","number":458,"stem":"（ ）民航安检工作现场岗位工作人员发现现场问题复杂、处置依据不明或者无权处置的，应当报告民航安检工作现场值班领导进行处理。（民用航空安全检查手册第四章民航安检工作实施第六十九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-459","type":"judge","number":459,"stem":"（ ）民航安检工作勤务中发生的案（事）件，应当按照民航安检案（事）移交报告有关规定和程序，将相关人员、物品和证据材料，移交报告指定部门。（民用航空安全检查手册第四章民航安检工作实施第七十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-460","type":"judge","number":460,"stem":"（ ）每日勤务开始前，民航安检机构勤务部门应当根据当日信息，分配勤务工作，调配勤务用品。分配勤务时应当定人员、定岗位、定任务、定责任。（民用航空安全检查手册第四章民航安检工作实施第七十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-461","type":"judge","number":461,"stem":"（ ）民航安检机构勤务部门应当根据民航安检机构勤务安排，按职责、按阶段开展民航安检勤务工作。（民用航空安全检查手册第四章民航安检工作实施第七十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-462","type":"judge","number":462,"stem":"（ ）当日民航安检勤务开始前，民航安检机构勤务部门应当对候机隔离区进行巡视、清场，实施机场控制区持续安保管制的运输机场除外。（民用航空安全检查手册第四章民航安检工作实施第七十三条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-463","type":"judge","number":463,"stem":"（ ）民航安检员上岗执勤前，应当以班组为单位，互相检查人身、物品、执勤着装和仪容，正确佩戴机场控制区通行证件。民用航空安全检查手册第四章民航安检工作实施第七十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-464","type":"judge","number":464,"stem":"（ ）当班勤务开展前，应当由当班勤务科、队（或者班、组）长组织班前工作布置会，检查民航安检员到岗情况和人员着装仪容、证件佩戴情况，传达上级通知和指示，按照航班预报信息合理安排勤务。（民用航空安全检查手册第四章民航安检工作实施第七十五条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-465","type":"judge","number":465,"stem":"（ ）交接班记录应当包括上级的文件、指示，勤务遇到的问题及处理情况，民航安检设备状态，勤务用品使用情况，勤务遗留问题及注意事项和其他需要交接的事项。（民用航空安全检查手册第四章民航安检工作实施第七十六条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-466","type":"judge","number":466,"stem":"（ ）当班勤务结束后，应当由当班勤务科、队、班、组长分级开展班后工作讲评，总结当班勤务执勤情况，点评当班勤务典型案例和特殊情况处置，提出工作改进要求。（民用航空安全检查手册第四章民航安检工作实施第七十七条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-467","type":"judge","number":467,"stem":"（ ）当天（班）勤务结束，民航安检机构勤务部门应当清点、存放、交接民航安检设备、勤务用品、关闭、妥善保管各种设备设施，清理民航安检工作场地并对现场进行锁闭或者持续实施安保控制，总结、登记勤务情况和处理结果。（民用航空安全检查手册第四章民航安检工作实施第七十八条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-468","type":"judge","number":468,"stem":"（ ）对禁止旅客随身携带但可作为托运行李运输的物品和限制旅客随身携带物品的超量部分，民航安检机构应当告知旅客可以办理行李托运手续、自行处理或者暂存（民用航空安全检查手册第四章民航安检工作实施第七十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-469","type":"judge","number":469,"stem":"（ ）对民航安检工作现场发现的旅客遗失物品，应当由当班安检员清点、登记后，移交运输机场公司指定部门处理，并做好书面交接记录。(民用航空安全检查手册第四章民航安检工作实施第八十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-470","type":"judge","number":470,"stem":"（ ）对在民航安检工作现场发现的自弃物品，民航安检机构根据有关处置程序要求，及时移交自弃物品接收部门，并做好书面交接记录。（民用航空安全检查手册第四章民航安检工作实施第八十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-471","type":"judge","number":471,"stem":"（ ）民航安检机构设立单位应当制定物品管理制度，对在民航安检现场暂存、自弃和遗失的物品进行有效管理，并建立台帐记录（民用航空安全检查手册第四章民航安检工作实施第八十三条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-472","type":"judge","number":472,"stem":"（ ）验证检查是指对旅客的乘机身份证件和乘机凭证进行查验。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-473","type":"judge","number":473,"stem":"（ ）人工检查是指通过人工方式检查证件的外观式样、规格、印刷和照片等主要识别特征，确认有无变造、伪造的疑点，有无揭换照片。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-474","type":"judge","number":474,"stem":"（ ）乘坐国际、地区航班旅客的验证检查第一步为核实有效乘机凭证的姓名与旅客证件姓名一致。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-475","type":"judge","number":475,"stem":"（ ）对于带墨镜、围巾遮挡面部、戴口罩、戴帽子、面饰等影响人、证识别或面部图像采集的旅客，应要求其摘下后进行验证检查工作。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-476","type":"judge","number":476,"stem":"（ ）旅客接受人身检查前，前传引导检查员应告知待检旅客，将随身物品、托运行李内的便携式电子设备、备用锂电池、充电宝、液态物品和旅客身着的厚重衣物等可能影响民航安检设备检查效果的物品单独取出，放置在行李托盘内接受民航行李安检设备检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十八条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-477","type":"judge","number":477,"stem":"（ ）手工人身检查原则上应当采用手持金属探测器配合手工检查的方式，但是基于旅客健康或者无法使用手持金属探测器的，也可以采用纯手工检查方式。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第八十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-478","type":"judge","number":478,"stem":"（ ）如果手持金属探测器报警，人身检查员应当要求旅客取出物品并进行检查确认后即可进行下一步检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第九十条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-479","type":"judge","number":479,"stem":"（ ）当旅客通过安全门报警，民航安检员对旅客进行手工人身复查时，应当在手不离开旅客衣物或者身体的情况下，顺着旅客身体的自然姿态，双手配合，以适当的力度通过摸、按、压等方法，检出民航禁限物品。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第九十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-480","type":"judge","number":480,"stem":"（ ）对旅客进行手工人身检查时,应当注意观察旅客神态及肢体语言,表现异常的,应当从严进行人身检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第九十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-481","type":"judge","number":481,"stem":"（ ）手工人身检查的重点部位包括头部、手腕及手部、肩胛、胸部、臀部、腋下、裆部、腰部、腹部、脚及脚踝。(民用航空安全检查工作手册第五章 旅客、行李物品的安全检查及处置第九十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-482","type":"judge","number":482,"stem":"（ ）对旅客衣领、帽子(帽兜)、领带、围巾(围脖)、腰带(腰封)、鞋、挽起的袖管和裤管、手套等可能会藏匿物品的介质应进行检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第九十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-483","type":"judge","number":483,"stem":"（ ）对旅客纯手工人身检查出的物品，应进行安全确认，并对查出放置物品的部位进行复检。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第九十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-484","type":"judge","number":484,"stem":"（ ）旅客基于风俗、宗教信仰等原因，要求由同性别民航安检员实施手工人身检查的，应当满足其要求。(民用航空安全检查手册第五章旅客、行李物品的安全检查与处置第九十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-485","type":"judge","number":485,"stem":"（ ）旅客随身携带、托运的行李物品经过民航行李安检设备后，民航行李安检设备操作员应当综合使用设备功能键对图像进行处理，并利用图像判读方法进行图像判读并做出放行决定。(民用航空安全检查手册第五章行李物品检查第九十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-486","type":"judge","number":486,"stem":"（ ）行李物品的检查图像出现断层或错位的，应当重新通过民航行李安检设备检查。(民用航空安全检查手册第五章行李物品检查第九十八条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-487","type":"judge","number":487,"stem":"（ ）行李物品的检查图像出现图像模糊不清、射线穿不透、无法判读图像的情况，应当重新通过民航行李安检设备检查。(民用航空安全检查手册第五章行李物品检查第九十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-488","type":"judge","number":488,"stem":"（ ）旅客托运行李需要开箱包检查的，开箱包检查员应当控制托运行李并与旅客确认箱包归属后，对行李图像标注的重点区域进行开箱包检查，必须与民航行李安检设备操作员进行开检确认。(民用航空安全检查手册第五章行李物品检查第一百零一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-489","type":"judge","number":489,"stem":"（ ）开箱包音视频记录、公共航空运输企业与旅客约定副本和书面告知书副本等证据材料依法应当至少保存两年。(民用航空安全检查工作手册第五章 旅客、行李物品的安全检查及处置第一百零二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-490","type":"judge","number":490,"stem":"（ ）对国际中转旅客，其直挂托运行李经民航行李安检设备检查后，需要进行开箱包检查的，应当要求国际中转旅客在场，但公共航空运输企业与旅客有特殊约定的除外。(民用航空安全检查手册第五章行李物品检查第一百零三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-491","type":"judge","number":491,"stem":"（ ）对公共航空运输企业责任原因漏运、错运的行李中发现民航禁限运输物品的，通知机场公安机关处理。(民用航空安全检查手册第五章行李物品检查第一百零四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-492","type":"judge","number":492,"stem":"（ ）使用民航痕量爆炸物探测设备对相关行李物品进行采样时，应当保证采样的完整性和范围覆盖性，除了对拉链、把手、口袋等重点位置外，还应当环绕行李物品外部一周并对行李内部进行取样。(民用航空安全检查手册第五章行李物品检查第一百零五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-493","type":"judge","number":493,"stem":"（ ）从严检查由与旅客同性别的两名民航安检员负责实施，其中一名负责监视受检旅客，防止其做出危险行为或毁灭物证，另一名实施检查。(民用航空安全检查手册第五章情况处置第一百零六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-494","type":"judge","number":494,"stem":"（ ）对旅客要求实施非公开检查的，在报民航安检机构现场值班领导批准后，民航安检员可对旅客人身或其行李物品进行非公开检查。(民用航空安全检查手册第五章情况处置第一百零七条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-495","type":"judge","number":495,"stem":"（ ）从严检查和非公开检查应当做出书面记录，记录内容包括受检旅客的姓名、证件号码、座位号、检查结论及处置信息，记录应当由批准实施检查的民航安检机构现场值班领导及实施检查人员共同签字。(民用航空安全检查手册第五章情况处置第一百零八条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-496","type":"judge","number":496,"stem":"（ ）发生航空器停场期间被非法接触的情形，根据运输机场公司指令，民航安检机构应当会同民用机场公安机关，对航空器进行安保搜查。(民用航空安全检查手册第五章情况处置第一百零九条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-497","type":"judge","number":497,"stem":"（ ）发生非法干扰行为，公共航空运输企业要求实施航空器安保检查、搜查的，民航安检机构应当组织对航空器实施安保检查、搜查，但是民航安检机构有明确证据确认安全的，可不再实施。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-498","type":"judge","number":498,"stem":"（ ）民航安检机构不负责旅客中途下机或者临时中止行程后，对航空器客舱进行的安保检查工作。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十一条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-499","type":"judge","number":499,"stem":"（ ）乘坐国内航班的旅客有效乘机身份证件过期的，不予放行。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-500","type":"judge","number":500,"stem":"（ ）境外旅客（包括外籍旅客，港、澳、台旅客）因有效乘机身份证件遗失或者办理有效乘机身份证件签证延期不能出示的，可凭公安机关出入境管理部门出具的贴有本人近期免冠证件照、并注明有效期的护照报失证明、外国人签证证件受理回执检查放行，要素不全的，不予放行。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-501","type":"judge","number":501,"stem":"（ ）对乘坐国内航班的有效乘机身份证件遗失、过期、损坏或者因故不能出示的中国境内公民，旅客申领居民身份证期间，公安机关出具的贴有本人近期免冠证件照、并加盖户籍专用章的《申领居民身份证回执》，核验其要素齐全的，予以放行。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-502","type":"judge","number":502,"stem":"（ ） 执行机要交通运输的机要交通员乘坐民航班机，其有效乘机凭证姓名与有效乘机身份证件不一致的，不予放行。(民用航空安全检查工作手册第五章旅客、行李物品的安全检查及处置第一百一十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-503","type":"judge","number":503,"stem":"（ ）持有西藏自治区公安、外事部门颁发的有效在华居留许可证的外籍旅客可以在没有《进藏批准函》或者《旅藏确认函》的情况下乘坐进藏航班。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十七条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-504","type":"judge","number":504,"stem":"（ ）中央对台办接待的保密客人，凭中央对台办出具的免检介绍信，免验其身份证件。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十八条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-505","type":"judge","number":505,"stem":"（ ）对国内航班旅客验证检查中遇有港澳居民使用香港、澳门特别行政区护照或香港、澳门特别行政区政府签发的身份证件的不予放行。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百一十九条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-506","type":"judge","number":506,"stem":"（ ）持有公安机关签发的错误或者要素不全的身份证明的不予放行，报告民用机场公安机关处理。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百二十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-507","type":"judge","number":507,"stem":"（ ）警卫人员执行警卫任务的，其人身及随身行李物品免予安全检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百二十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-508","type":"judge","number":508,"stem":"（ ）佩戴心脏起搏器或怀孕的旅客提出纯手工检查要求的，可不要求其通过民航人身安检设备，对其实施纯手工人身检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百二十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-509","type":"judge","number":509,"stem":"（ ）携带婴儿的旅客，大人及婴儿尽量分开进行人身检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百二十四条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-510","type":"judge","number":510,"stem":"（ ）对残疾旅客的检查由同性别人员实施，检查标准与正常旅客一致。(民用航空安全检查工作手册第五章旅客、行李物品的安全检查及处置第一百二十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-511","type":"judge","number":511,"stem":"（ ）对服务犬进行检查时，使用手持金属探测器沿服务犬的身体形状贴紧犬身进行检查。(民用航空安全检查工作手册第五章旅客、行李物品的安全检查及处置第一百二十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-512","type":"judge","number":512,"stem":"（ ）押解犯罪嫌疑人乘机的，民航安检员应当查验民用机场公安机关出具的《押解犯罪嫌疑人乘机通知书》，对押解人员及犯罪嫌疑人进行正常检查。无疑点的，留存《押解犯罪嫌疑人乘机通知书》第二联登记放行。(民用航空安全检查手册第五章情况处置第一百二十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-513","type":"judge","number":513,"stem":"（ ）对打绷带、石膏的旅客，应查验其医院证明，对于没有医院证明的，应当进行从严检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百二十八条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-514","type":"judge","number":514,"stem":"（ ）对乘坐急救车辆进入客机坪的危重伤病旅客，检查无误后，留存其医院证明证明和医疗物品配备清单，并将乘机人员安检信息录入民航安检信息管理系统或者进行手工登记。(民用航空安全检查手册第五章情况处置第一百二十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-515","type":"judge","number":515,"stem":"（ ）发现精神病患者或健康状况可能危及自身或影响其他旅客安全的旅客，通知民用机场公安机关处理。(民用航空安全检查手册第五章情况处置第一百三十条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-516","type":"judge","number":516,"stem":"（ ）乘坐国际航班旅客携带的液态化妆品，不属于航空旅行途中自用的，不得随身携带。(民用航空安全检查手册第五章情况处置第一百三十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-517","type":"judge","number":517,"stem":"（ ）专业照相器材，精密仪器原则上应通过民航行李安检设备检查；旅客提出不能通过民航行李安检设备的，应当进行手工检查和防爆检查，并可要求旅客进行操作演示。(民用航空安全检查手册第五章情况处置第一百三十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-518","type":"judge","number":518,"stem":"（ ）对通过民航行李安检设备的电子产品、设备的图像有疑点的，可要求旅客进行开箱查验，开箱查验与常规操作不符或与同类型电子产品重量不符的，应进一步检查确认。(民用航空安全检查手册第五章情况处置第一百三十三条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-519","type":"judge","number":519,"stem":"（ ）旅客携带骨灰盒乘机的，骨灰盒原则上应通过民航安检设备检查，对于X射线无法穿透的，应当要求旅客出具火化证明、死亡证明等证明材料并实施爆炸物探测检查。必要时，可在非公开场合进行开箱检查确认。(民用航空安全检查手册第五章情况处置第一百三十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-520","type":"judge","number":520,"stem":"（ ）对旅客携运的需要公共航空运输企业批准方可运输的物品，如超规锂电池、干冰、供医用的气态氧气瓶或空气瓶等，应当要求出具相关公共航空运输企业或其地面服务代理机构书面同意运输证明。相关物品通过安全检查确认安全后方可直接放行。(民用航空安全检查手册第五章情况处置第一百三十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-521","type":"judge","number":521,"stem":"（ ）造血干细胞作为随身行李物品运输的，应当要求出具中国造血干细胞捐献者资料库管理中心出具并加盖省级分库公章的介绍信，核验储运箱上的中华骨髓库标志，对造血干细胞通过民航行李安检设备进行检查，对不宜通过的，应当进行手工检查和爆炸物探测检查。(民用航空安全检查手册第五章情况处置第一百三十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-522","type":"judge","number":522,"stem":"（ ）旅客携运属于自用的含有锂电池的便携式电子设备（如手表、计算器、照相机、手机、笔记本电脑、便携式摄像机等）可以作为行李物品运输。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百三十八条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-523","type":"judge","number":523,"stem":"（ ）检查旅客及其行李物品发现拆解打火机、火柴的，应当从严检查，并对其同行人员也进行从严检查(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百三十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-524","type":"judge","number":524,"stem":"（ ）司法机关和军队政法部门携运的属于物证的枪支、弹药、仿真枪的，可以作为行李物品运输；对于其他旅客携运的枪支及其仿真品、弹药，应告知其不得作为行李物品运输，并报告民用机场公安机关处理。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百四十条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-525","type":"judge","number":525,"stem":"（ ）军警人员携运手铐、警绳，应当告知不得作为行李物品运输，并报告民用机场公安机关。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百四十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-526","type":"judge","number":526,"stem":"（ ）属于少数民族人员在民族自治区内携运或者境外旅客携运民族刀具的，可以作为托运行李运输；其他人员携运民族刀具的，报告民用机场公安机关处理(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百四十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-527","type":"judge","number":527,"stem":"（ ）免检物品携运人员人身及其携运的其他行李物品,不属于免检范围的,应当接受安全检查。(民用航空安全检查手册第五章旅客、行李物品的安全检查及处置第一百四十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-528","type":"judge","number":528,"stem":"（ ）旅客行李物品安全检查包括文件审核、设备检查、开箱包检查以及民航局规定的其他检查方式等。(民用航空安全检查手册第六章航空货物检查第一百四十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-529","type":"judge","number":529,"stem":"（ ）航空货物通过民航货邮安检设备检查前，货邮快件安检设备操作员应当要求托运人或者航空货运销售代理人提供航空货物运输文件资料。(民用航空安全检查手册第六章航空货物检查第一百四十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-530","type":"judge","number":530,"stem":"（ ）对航空货物生成的图像，货邮快件安检设备操作员应当对照航空货物安检申报清单上的品名，进行技术判读和核查。(民用航空安全检查手册第六章航空货物检查第一百四十七条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-531","type":"judge","number":531,"stem":"（ ）货邮快件开箱检查员接到开箱检查指令后，应当与货邮快件安检设备操作员进行指令复述确认，并对航空邮件进行开箱检查，与货邮快件安检设备操作员进行确认。(民用航空安全检查手册第六章航空货物检查第一百四十八条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-532","type":"judge","number":532,"stem":"（ ）使用民航痕量爆炸物探测设备对航空货物进行采样时，应当保证采样的完整性和范围覆盖性，除了航空货物外包装拉链、把手、口袋等重点位置外，还应当对航空货物外包装的内容物进行取样。(民用航空安全检查手册第六章航空货物检查第一百四十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-533","type":"judge","number":533,"stem":"（ ）对于单体超大、超量无法通过民航货邮安检设备检查的航空货物，民航安检机构可以采取隔离停放24小时措施，并对航空货物实施防爆检查。必要时可实施开箱检查。(民用航空安全检查手册第六章航空货物检查第一百五十条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-534","type":"judge","number":534,"stem":"（ ）对适合通过民航货邮安检设备检查且符合隔离停放24小时要求的航空货物，应当实施开箱检查和防爆检查或者通知公共航空运输企业拒绝收运。(民用航空安全检查手册第六章航空货物检查第一百五十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-535","type":"judge","number":535,"stem":"（ ）对经安全检查，确认安全的航空货物，应当在航空货运单、航空货物安检申报清单上加注安检验讫标识，并留存航空货物安检申报清单后放行。(民用航空安全检查手册第六章航空货物检查第一百五十二条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-536","type":"judge","number":536,"stem":"（ ）对于经过安全检查仍然无法确定货物性质或者无法确认安全的，民航安检员应当在航空货运单、航空货物安检申报清单加注退运标识，做退运处理，并留存航空货运单。(民用航空安全检查手册第六章航空货物检查第一百五十三条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-537","type":"judge","number":537,"stem":"（ ）航空邮件申请安检前，邮政企业应当保证邮包封口、包装完好且单个邮包重量不超过30千克，并在安检申报清单上确认上述信息。(民用航空安全检查手册第六章航空货物检查第一百五十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-538","type":"judge","number":538,"stem":"（ ） 从事航空邮件检查的民航货邮安检设备的最大通道尺寸不得超过100厘米×100厘米。(民用航空安全检查手册第六章航空货物检查第一百五十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-539","type":"judge","number":539,"stem":"（ ）对航空邮件生成的图像，货邮快件安检设备操作员应当对照航空邮件品名、性质清单上的品名、内容，进行技术判读和核查。(民用航空安全检查手册第六章航空货物检查第一百五十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-540","type":"judge","number":540,"stem":"（ ）货邮快件开箱检查员接到开箱检查指令后，应当与货邮快件安检设备操作员进行指令复述确认，并会同邮政企业人员对航空邮件进行开箱检查，开箱检查结果应当与货邮快件安检设备操作员进行确认。(民用航空安全检查手册第六章航空货物检查第一百五十八条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-541","type":"judge","number":541,"stem":"（ ）使用民航痕量爆炸物探测设备对航空邮件进行采样时，应当保证采样的完整性和范围覆盖性，除了航空邮件顶端、底端、接缝处等重点位置外，还应当对具体航空邮件的内部进行取样。(民用航空安全检查手册第六章航空货物检查第一百五十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-542","type":"judge","number":542,"stem":"（ ）对经安全检查确认安全的航空邮件，应当在航空邮件邮包汇总路单、航空邮件安检申报清单上加注安检验讫标识，并留存航空邮件安检申报清单和航空邮件品名、数量详细清单后放行。(民用航空安全检查手册第六章航空货物检查第一百六十条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-543","type":"judge","number":543,"stem":"（ ）航空快件运输资料审查合规的，货邮快件安检设备操作员应当根据航空快件汇总包裹尺寸、内容物选择合适的民航货邮安检设备，组织将航空快件汇总包裹单排、间隔放置在民航货邮安检设备传送带上，逐一通过设备检查。(民用航空安全检查手册第六章航空货物检查第一百六十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-544","type":"judge","number":544,"stem":"（ ）对航空快件生成的图像，货邮快件安检设备操作员应当对照航空货运单航空快件申报品名，进行技术判读和核查，遇到图像模糊不清、射线穿不透、图像无法识别的可不进行开箱确认。(民用航空安全检查手册第六章航空货物检查第一百六十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-545","type":"judge","number":545,"stem":"（ ）货邮快件开箱检查员接到开箱检查指令后，应当与货邮快件安检设备操作员进行指令复述确认，并对航空快件进行开箱检查，开箱检查结果应当与货邮快件安检设备操作员进行确认。(民用航空安全检查手册第六章航空货物检查第一百六十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-546","type":"judge","number":546,"stem":"（ ）使用民航痕量爆炸物探测设备对航空快件进行采样时，应当保证采样的完整性和范围覆盖性，除了航空快件拉链、把手、口袋处等重点位置外，还应当对具体航空快件的外围一周及其内容物进行取样。(民用航空安全检查手册第六章航空货物检查第一百六十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-547","type":"judge","number":547,"stem":"（ ）航空快件中含有国家法律规定的违禁物品、管制器具和其他禁止寄递物品的，要移交机场海关处理。(民用航空安全检查手册第六章航空货物、航空邮件的安全检查及处置第一百六十八条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-548","type":"judge","number":548,"stem":"（ ）航空货运单或者航空邮件汇总路单未经公共航空运输企业或者其地面服务代理机构收运审核的，货邮快件安检设备操作员应当退回航空货物、航空邮件运输文件资料，不予受理。(民用航空安全检查手册第六章航空货物检查第一百六十九条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-549","type":"judge","number":549,"stem":"（ ）遇有过检后无图像的，航空货物、航空邮件应当重新通过民航货邮安检设备检查。(民用航空安全检查手册第六章航空货物检查第一百七十条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-550","type":"judge","number":550,"stem":"（ ）航空货物、航空邮件开箱检查在航空器维修区内进行的，应当指定专门的隔离存放区域，并保证可疑货物、邮件与已检货物、邮件不相混。(民用航空安全检查手册第六章航空货物检查第一百七十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-551","type":"judge","number":551,"stem":"（ ）遇有在航空邮件、快件中隐匿、夹带运输违禁物品的，民航安检员应当控制相关航空货物、航空邮件，留存相关运输资料和证据材料，报告民航安检机构处置，不得退运处理。(民用航空安全检查手册第六章航空货物检查第一百七十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-552","type":"judge","number":552,"stem":"（ ）属于国家规定的免检货物，核验民航局公安局出具的免检证明，免检放行，并留存民航局公安局免检证明。(民用航空安全检查手册第六章航空货物检查第一百七十三条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-553","type":"judge","number":553,"stem":"（ ）对安检过程中发现可疑情形，需要进一步检查确认时，托运人或者航空货运销售代理人不配合或者要求退运的，应当同意托运人或者航空货运销售代理人要求，并加注退运标识。(民用航空安全检查手册第六章航空货物检查第一百七十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-554","type":"judge","number":554,"stem":"（ ）对运离机场控制区的中转航空货物、航空邮件，重新进入机场控制区的，不需要重新进行安全检查。(民用航空安全检查手册第六章航空货物检查第一百七十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-555","type":"judge","number":555,"stem":"（ ）执行飞行任务的机组人员及其行李物品应当在指定通道接受安全检查，检查包括证件检查、人身检查和行李物品检查等。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百七十六条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-556","type":"judge","number":556,"stem":"（ ）对临时借调其他公共航空运输企业执行本公共航空运输企业飞行任务的机组人员，还应当要求提供民航地区管理局签发的备案证明。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百七十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-557","type":"judge","number":557,"stem":"（ ）对机组人员进行人身检查前，应当要求机组人员提前将随身物品、便携式电子设备、备用锂电池、充电宝、液态物品和衣服等可能影响民航安检设备检查效果的物品单独取出，放置在行李托盘内接受民航行李安检设备检查。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百七十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-558","type":"judge","number":558,"stem":"（ ）执行飞行任务的机组人员的行李物品中个人自用的梳妆用品、日用品等液态物品的数量、容器规格不受限制，但应当单独取出接受检查。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百八十条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-559","type":"judge","number":559,"stem":"（ ）对中国民航空保人员携带的使用锂电池的用于防爆检查的痕量爆炸物探测设备，通过民航行李安检设备检查后予以放行，并确认锂电池额定能量。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-560","type":"judge","number":560,"stem":"（ ）外国空警人身及其他物品按照旅客检查标准正常接受安全检查。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-561","type":"judge","number":561,"stem":"（ ）进入机场控制区的工作人员及其他人员应当在指定通道接受安全检查，检查包括证件检查、人身检查、携带的个人物品检查。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十四条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-562","type":"judge","number":562,"stem":"（ ）对工作人员的验证检查，应当查验其机场控制区通行证件和有效身份证件，进行人证对照检查，确认证件是否在有效期内，查看持证人到达的区域是否与证件限定的区域相符。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十五条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-563","type":"judge","number":563,"stem":"（ ）对持机场公安机关签发的特别通行证进入机场控制区的人员的证件检查，应当查验证件真伪及有效期、并进行人证对照。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-564","type":"judge","number":564,"stem":"（ ）对进入机场控制区迎送客人的各驻华外交机构人员（包括大使和代表夫妇）、领事官员及上述人员家属，应当核查其外交人员证，并对其人身及携带物品正常进行安全检查。(民用航空安全检查手册第七章其他人员、物品安全检查第一百八十九条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-565","type":"judge","number":565,"stem":"（ ）工具、物料和器材所在单位应当与运输机场公司签订运送安全管理协议并向民航安检机构登记备案。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-566","type":"judge","number":566,"stem":"（ ）工具、物料、器材含有其他危险品的，或者工具属于民航禁限运输的锐器、钝器，民航安检机构应当查验运输机场公司同意证明。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-567","type":"judge","number":567,"stem":"（ ）对货物托运人的航材，作为航空货物运输的，按照航空货物安全检查标准进行检查。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-568","type":"judge","number":568,"stem":"（ ）公安、急救、消防等车辆因参与应急救援保障任务需要进入机场控制区时，应当予以优先安检，快速放行。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-569","type":"judge","number":569,"stem":"（ ）航空配餐、机供品、商品销售（使用）单位应当与运输机场公司签订运送安全管理协议，所运物品进入候机隔离区时，应当在指定通道接受安全检查。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十七条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-570","type":"judge","number":570,"stem":"（ ）对未使用封闭货车运输的航空配餐和机供品，民航安检机构应当核对航空配餐和机供品台账，使用民航安检设备对航空配餐和机供品进行检查，对货车实施检查，确认安全后登记放行。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第一百九十九条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-571","type":"judge","number":571,"stem":"（ ）乘坐公务机的旅客、机组人员，在机长陪同下接受安全检查；公务机公司或其地面代理机构开具的旅客人员名单可视为有效乘机凭证；机组人员需查验其机组人员证件。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第二百零二条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-572","type":"judge","number":572,"stem":"（ ）航空军事运输安全检查按照《航空军事运输安全检查与飞机监护、守卫暂行规定》（﹝1992﹞后交字第(206)号）执行。(民用航空安全检查手册第七章其他人员、物品的安全检查及处置第二百零三条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-573","type":"judge","number":573,"stem":"（ ）外国专机人员的人身检查参照上述要求实施，行李物品的安全检查按照中方要求由运输机场安检部门协助实施（民用航空安全检查手册第七章其他人员、物品的安全检查及处置第二百零四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-574","type":"judge","number":574,"stem":"（ ）民航行政机关应制定应急处置预案及预案管理程序，规范安全检查应急管理及处置工作，有效应对突发事件。（民用航空安全检查工作手册第八章应急处置第二百零七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-575","type":"judge","number":575,"stem":"（ ）民航安检工作应急处置预案管理程序应当包括预案文件的编制或修订、审核、批准、生效、检验和评估。（民用航空安全检查工作手册第八章应急处置第二百零九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-576","type":"judge","number":576,"stem":"（ ）民航安检机构应根据实际情况与相关单位建立、健全应急响应信息联动工作程序，以确保信息传递及时、准确、客观、全面。（民用航空安全检查工作手册第八章应急处置第二百一十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-577","type":"judge","number":577,"stem":"（ ）民航安检工作中发现民用机场公安机关布控的犯罪嫌疑人的，应与公共航空运输企业确认是否有同行人员及其安检情况。（民用航空安全检查工作手册第八章应急处置第二百一十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-578","type":"judge","number":578,"stem":"（ ）本场起飞的尚未或者正在安检的航班，遇到非法干扰行为的，应当加强民航安检勤务安排，对乘坐该航班的旅客、行李物品、航空货物、航空货邮进行严格检查。（民用航空安全检查工作手册第八章应急处置第二百一十五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-579","type":"judge","number":579,"stem":"（ ）遇有民航安检现场发生暴力恐怖袭击事件时，同时撤离至安全区域，报告民用机场公安机关到场处置。（民用航空安全检查工作手册第八章应急处置第二百一十六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-580","type":"judge","number":580,"stem":"（ ）遇有待检区发现无人看管、认领行李时，应报告民用机场公安机关，控制无人看管、认领的行李，等待民用机场公安机关开展处置工作。（民用航空安全检查工作手册第八章应急处置第二百一十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-581","type":"judge","number":581,"stem":"（ ）遇有人员在民航安检现场长时间聚集、散发未申报宣传品时，应予以制止，并报民用机场公安机关到场处置。（民用航空安全检查工作手册第八章应急处置第二百一十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-582","type":"judge","number":582,"stem":"（ ）民航安检工作中遇有航班大面积延误时，应加强与公共航空运输企业和运输机场公司的信息沟通，注意观察现场情况，做好勤务准备工作。（民用航空安全检查工作手册第八章应急处置第二百一十九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-583","type":"judge","number":583,"stem":"（ ）遇有安检设备、信息系统故障且无法排除的，及时维持现场秩序，防止发生拥堵及冲闯事件，同时做好相关解释工作，并将故障情况及时通报有关单位。（民用航空安全检查工作手册第八章应急处置第二百二十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-584","type":"judge","number":584,"stem":"（ ）遇有安检现场发生危险品事件（故）时，应对危险品进行清理，防止无关人员接触该物品，并对可疑人员进行有效控制，同时关闭安检通道，联系有关单位到场救助，做好个人防护和后续处理工作。（民用航空安全检查工作手册第八章应急处置第二百二十一条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-585","type":"judge","number":585,"stem":"（ ）遇有民航安检现场发生踩踏事件（故）时，应进行语言提示，疏散无关人员，同时关闭安检通道，报告有关单位开展救援工作。（民用航空安全检查工作手册第八章应急处置第二百二十二条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-586","type":"judge","number":586,"stem":"（ ）民航安检机构应当根据民航局民航安检质量控制相关规定和其设立单位航空安保质量控制方案，制定本机构民航安检工作质量控制管理规定。（民用航空安全检查工作手册第九章内部质量控制第二百二十三条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-587","type":"judge","number":587,"stem":"（ ）民航安检机构可以根据实际情况，配备质量控制管理人员指导、管理、监督和检查质量控制活动，全面监督，全面负责，保证各级质量控制活动充分发挥作用。（民用航空安全检查工作手册第九章内部质量控制第二百二十四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-588","type":"judge","number":588,"stem":"（ ）民航安检机构质量控制活动的主要方式包括内部监督、内部测试、内部演练，还包括内部考察、内部事件调查和内部审计等其他方式。（民用航空安全检查工作手册第九章内部质量控制第二百二十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-589","type":"judge","number":589,"stem":"（ ）质量控制活动记录内容应当包括质量控制活动方式、时间、实施和接受质量控制活动部门和人员、质量控制活动实施过程、实施结果以及其他应当记录的内容。（民用航空安全检查工作手册第九章内部质量控制第二百二十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-590","type":"judge","number":590,"stem":"（ ）质量控制活动分析报告应当包括质量控制活动时间，地点，实施和接受质量控制活动的人员，质量控制活动的方式、实施过程，实施结果，质量控制活动结论，整改要求和改进措施等。（民用航空安全检查工作手册第九章内部质量控制第二百三十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-591","type":"judge","number":591,"stem":"（ ）民航安检机构应当根据质量控制活动分析报告，要求相关单位采取整改措施。(民用航空安全检查手册第二百三十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-592","type":"judge","number":592,"stem":"（ ）民航安检机构应当根据质控部门或者质控管理岗位分析结论，定期发布质量控制活动情况通报，提出改进要求，以防范安全风险，提升工作质量。（民用航空安全检查工作手册第九章内部质量控制第二百三十三条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-593","type":"judge","number":593,"stem":"（ ）民航安检机构在日常工作中进行定期或不定期的内部监查。(民用航空安全检查手册第二百三十四条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-594","type":"judge","number":594,"stem":"（ ）内部检查应当着重执行民航安检工作标准要求的合规性验证。(民用航空安全检查手册第二百三十五条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-595","type":"judge","number":595,"stem":"（ ）内部测试可以采取隐匿测试或者公开测试的方式。(民用航空安全检查手册第二百三十六条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-596","type":"judge","number":596,"stem":"（ ）测试物品包括模拟爆炸装置、假（冒）证件、各类危险品、违禁品和限带品等。(民用航空安全检查手册第二百三十七条)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-597","type":"judge","number":597,"stem":"（ ）民航安检机构质量控制中实施内部测试，如果通过测试，测试人员应当告知被测试人员测试项目的测试点。（民用航空安全检查工作手册第九章内部质量控制第二百三十八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-598","type":"judge","number":598,"stem":"（ ）民航安检机构制定内部演练计划的内容应包括演练科目、演练时间、演练组织人员、演练参与人员、评估人员等。（民用航空安全检查工作手册第九章内部质量控制第二百三十九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-599","type":"judge","number":599,"stem":"（ ）内部演练的评估结果应适时通报有关部门，有关部门应当根据演练评估改进工作。(民用航空安全检查手册第二百四十一条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-600","type":"judge","number":600,"stem":"（ ）民航安检机构质量控制活动中内部审计既可覆盖民航安检管理体系全部要求和部门，也可针对专门要求或部门进行重点审核。（民用航空安全检查工作手册第九章内部质量控制第二百四十二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-601","type":"judge","number":601,"stem":"（ ）内部审计应根据实施计划以及具体检查单进行，对审计中发现的不符合项应与相关主要部门进行确认。(民用航空安全检查手册第二百四十三条)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-602","type":"judge","number":602,"stem":"（ ）发生安检不安全事件时，民航安检机构应当根据规定按职权，进行内部事件调查，以发现缺陷，改进工作，避免类似事件再次发生。（民用航空安全检查工作手册第九章内部质量控制第二百四十四条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-603","type":"judge","number":603,"stem":"（ ）民航安检机构质量控制活动中的内部事件调查时，应留存相关图像、数据、音视频等信息，并组织审计人员进行调查。（民用航空安全检查工作手册第九章内部质量控制第二百四十五条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-604","type":"judge","number":604,"stem":"（ ）民航安检机构质量控制活动中的内部事件调查内容对事件综合分析后，应确定事件性质、发生的原因、责任认定，提出纠正或预防措施，并形成调查报告。（民用航空安全检查工作手册第九章内部质量控制第二百四十六条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-605","type":"judge","number":605,"stem":"（ ）民航安检质量控制活动中对内部考察活动的验证包括文件审查、现场勘验、隐蔽测试。（民用航空安全检查工作手册第九章内部质量控制第二百四十七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-606","type":"judge","number":606,"stem":"（ ）国家保卫对象率领的出访代表团，除国家保卫对象外，其他人员必须接受检查。(《民用航空安全检查工作手册》附件四1.1)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-607","type":"judge","number":607,"stem":"（ ）应邀来我国访问(包括过境、非正式访问)的外国副总统、副总理、副议长以上领导人及其率领的代表团全体成员，需接受检查。(《民用航空安全检查工作手册》附件四1.2)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-608","type":"judge","number":608,"stem":"（ ）驻华大使馆大使或国际组织驻华代表机构代表夫妇在中国境内机场乘坐民航班机，凭外交护照，其人身及随身携带的手提行李物品免予检查。(民用航空安全检查手册附件四1.4)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-609","type":"judge","number":609,"stem":"（ ）大军区正职在职负责同志率团出访，本人免予检查。(《民用航空安全检查工作手册》附件四1.5)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-610","type":"judge","number":610,"stem":"（ ）军队在职副军职少将以上的负责人属于重要旅客范围。(《民用航空安全检查工作手册》附件四2.2)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-611","type":"judge","number":611,"stem":"（ ）由各部、委以上单位或我驻外使、领馆提出要求按重要旅客接待的客人属于重要旅客。(《民用航空安全检查工作手册》附件四2.4)","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-612","type":"judge","number":612,"stem":"（ ）民航安检肩章实行分级管理,根据职务级别及职称等级分为四级。（民用航空安全检查工作手册附件二民航安检工作人员着装和仪容管理要求1.5）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-613","type":"judge","number":613,"stem":"（ ）男性民航安检员头发应干净整洁、发色自然，不得蓄长发、大鬓角、不得寸头或留其他极端、怪异发型。（民用航空安全检查工作手册附件二民航安检工作人员着装和仪容管理要求2.3.1)","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-614","type":"judge","number":614,"stem":"( )民航安检机构在安检设备开启接通并投入使用前,应当对民航在用安检设备开展日常检测,确认设备处于正常状态。（民用航空安全检查工作手册补充手册第二条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-615","type":"judge","number":615,"stem":"( )对安检在用设备，民航安检机构应当至少每24小时做一次日常检测。（民用航空安全检查工作手册补充手册第二条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-616","type":"judge","number":616,"stem":"( )对通过民航人身安检设备检查未报警的旅客、工作人员及其他人员,应当进行手工人身随机抽检,抽检比例由民航地区管理局自行制定。（民用航空安全检查工作手册补充手册第三条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-617","type":"judge","number":617,"stem":"( )对通过民航行李安检设备检查确认有疑点的旅客随身行李物品、工作人员及其他人员携带的物品,应采取手工检查、防爆检查或两者相结合的方式进行随机抽检。（民用航空安全检查工作手册补充手册第四条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-618","type":"judge","number":618,"stem":"( )民航安检机构应当通过现场检查和审查台账记录等方式对多级行李检查系统的剔除率进行监测。（民用航空安全检查工作手册补充手册第五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-619","type":"judge","number":619,"stem":"( )民航安检机构使用分级行李检查系统的,应当根据安检设备的规格和检测能力设置每一级检查系统对可疑行李的剔除率。（民用航空安全检查工作手册补充手册第五条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-620","type":"judge","number":620,"stem":"( )剔除率是指多级行李检查系统自动判定或者人工判图需要进一步检查的行李所占比例。（民用航空安全检查工作手册补充手册第五条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-621","type":"judge","number":621,"stem":"( )行李物品的检查图像中发现致密区域或不透明区域的,民航行李安检设备操作员应当通知开箱包检查员开箱包检查,必要时增加爆炸物探测检查。（民用航空安全检查工作手册补充手册第六条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-622","type":"judge","number":622,"stem":"( )旅客基于风俗、宗教信仰等原因,要求对其随身携带具有宗教意义的物品实施非公开检查的,可以对旅客行李物品进行私密检查。（民用航空安全检查工作手册补充手册第七条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-623","type":"judge","number":623,"stem":"( )对携运枪支、弹药的,民航安检机构应当在确保环境安全的前提下开展安全检查,确认枪弹分离、枪支内无子弹,检查过程防止无关人员接触,检查后登记放行。（民用航空安全检查工作手册补充手册第八条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-624","type":"judge","number":624,"stem":"( )进入机场控制区的车辆在接受安全检查期间,车内所有人员应携带个人物品离开车辆,人员及物品应当接受安全检查。（民用航空安全检查工作手册补充手册第九条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-625","type":"judge","number":625,"stem":"( )进入机场控制区的车辆在接受安全检查期间,必要时将车轮拱罩列入检查范围。（民用航空安全检查工作手册补充手册第九条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-626","type":"judge","number":626,"stem":"( )民航安检机构应当对需要进入机场控制区的机场供应品开展安全检查,《机场供应品禁止进入控制区物品目录》中的物品禁止进入。（民用航空安全检查工作手册补充手册第十条）","options":{"A":"正确","B":"错误"},"answer":"A","score":1},{"id":"judge-627","type":"judge","number":627,"stem":"( )《机场供应品禁止进入控制区物品目录》之外且属于民航禁限运输的物品,民航安检机构应当查验航空运输企业出具的同意证明,并对其实施检查、核对,登记后放行。（民用航空安全检查工作手册补充手册第十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-628","type":"judge","number":628,"stem":"( )机场供应品包括商品和供应品,指除工作人员及其他人员携带的物品以外,在机场控制区内以盈利为目的或活动而出售、使用或供应的所有物品。（民用航空安全检查工作手册补充手册第十条）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-629","type":"judge","number":629,"stem":"( )《机场供应品禁止进入机场控制区物品目录》中其他物品包括酒精体积百分含量大于65%的酒精饮料。（民用航空安全检查工作手册补充手册附件机场供应品禁止进入机场控制区物品目录）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-630","type":"judge","number":630,"stem":"( )根据《机场供应品禁止进入机场控制区物品目录》，强磁化物、有强烈刺激性气味或者引起人群恐慌的物品,以及不能判明性质可能具有危险性的物品属于危险物品。（民用航空安全检查工作手册补充手册附件机场供应品禁止进入机场控制区物品目录）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-631","type":"judge","number":631,"stem":"( )根据《机场供应品禁止进入机场控制区物品目录》，飞镖、弹弓、弓、箭、蜂鸣自卫器属于管制器具。（民用航空安全检查工作手册补充手册附件机场供应品禁止进入机场控制区物品目录）","options":{"A":"正确","B":"错误"},"answer":"B","score":1},{"id":"judge-632","type":"judge","number":632,"stem":"( )根据《机场供应品禁止进入机场控制区物品目录》，爆炸物质或燃烧物质和装置包括弹药、爆破器材、火药、烟火制品、地雷、烟雾制品,及上述物品的复制品和仿制品。（民用航空安全检查工作手册补充手册附件机场供应品禁止进入机场控制区物品目录）","options":{"A":"正确","B":"错误"},"answer":"B","score":1}];

